INSERT INTO `vest` (`id_vesti`, `naslov`, `sadrzaj`, `id_rubrike`, `status`, `datum_vreme_objave`, `id_novinara`, `broj_pozitivnih`, `broj_negativnih`, `id_urednika`, `lead_slika_url`) VALUES
(133, 'Dačić: Gvajana, naš sedmi prijatelj u Savetu bezbednosti UN', '<p>Prvi potpredsednik Vlade Srbije i ministar spoljnih poslova Ivica Dačić rekao je sinoć da je bitno &scaron;to je hitna sednica Saveta bezbednosti Ujedinjenih nacija uop&scaron;te održana, kao i da je bitno i to &scaron;to je ona bila otvorenog tipa i &scaron;to je predsednik Srbije Aleksandar Vučić čvrsto i argumentovano izneo sa kakvim se problemima i terorom suočava srpski narod na KiM. Gostujući na TV Pink, on je objasnio da je bilo potrebno obezbediti devet od 15 glasova, da bi sednica bila održana. Kako je rekao, odmah nakon podno&scaron;enja zahteva za hitnom sednicom pozvao je ministra spoljnih poslova Rusije Sergeja Lavrova koji je obećao da će dati sve od sebe da se sednica održi.</p>\r\n<p>&bdquo;Predsednik je zvao kineskog ambasadora. Ja sam pozvao ministra iz Mozambika, Sijera Leonea, Alžira, Ekvadora. Ali to je &scaron;est. &Scaron;ta je tu bilo ključno? Gvajana. Ta država je priznala Kosovo jo&scaron; 2013. i sa njima nemamo skoro nikakve odnose. Ali sam pozvao neke njihove prijatelje, koji su i na&scaron;i prijatelji, i uspostavili smo vezu sa ministrom spoljnih poslova Gvajane&rdquo;, naglasio je Dačić istakav&scaron;i da mu je posle dva razgovora ministar spoljnih poslova Gvajane javio da će Gvajana da donese odluku sama, kao predsedavajuća Savetu bezbednosti.</p>\r\n<p>Mnogi su se iznenadili jer nisu očekivali to da će Gvajana to da uradi. Eto, ako mogu da kažem, stekli smo i sedmog prijatelja u SB od 15&rdquo;, rekao je Dačić, koji je sinoć na aerodromu &bdquo;Nikola Tesla&rdquo; dočekao grčkog premijera Kirjakosa Micotakisa. Predsednik Vlade Grče danas boravi u zvaničnoj poseti na&scaron;oj zemlji, a sinoć je imao i neformalni susret s predsednikom Srbije&nbsp; Aleksandrom Vučićem.</p>\r\n<p>&nbsp;</p>\r\n<p style=\"text-align: center;\"><a href=\"https://www.politika.rs/sr/clanak/598872/Nestorovic-Ponoviti-izbore-u-Beogradu)\"><img style=\"width: 214px; height: 121px;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_Prof-dr-Branimir-Nestorovic-a-vasilj.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h4 style=\"text-align: center;\"><a href=\"https://www.politika.rs/sr/clanak/598872/Nestorovic-Ponoviti-izbore-u-Beogradu)\">Nestorović: Ponoviti izbore u Beogradu</a></h4>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;</p>', 1, 'odobrena', '2024-02-12 04:01:34', 27, 2, 0, 1, 'images/dacic.jpg'),
(135, 'Diplomatska pobeda Srbije', '<p>Govor predsednika Srbije u četvrtak na vanrednoj sednici Saveta bezbednosti UN o stanju na Kosovu i Metohiji izuzetno je važan i istorijski &ndash; jednodu&scaron;na je ocena domaćih zvaničnika, uz napomenu da je hitno održavanje vanredne sednice izuzetno značajno za Srbiju.</p>\r\n<p>Ministar spoljnih poslova u tehničkom mandatu i prvi potpredsednik vlade Ivica Dačić ocenio je da je &bdquo;Aleksandar Vučić u obraćanju SB Ujedinjenih nacija sve dobro odmerio i na jasan način, istorijski važan, pokazao &scaron;ta se de&scaron;ava na KiM i ko je krivac i kreator svega&rdquo;.</p>\r\n<p>On je u izjavi za Tanjug istakao da je bilo dovoljno argumenata da svako vidi &scaron;ta je sada osnovni problem i za&scaron;to je Srbija tražila tu hitnu sednicu, a to su nepo&scaron;tovanje raznih rezolucija i SB i Briselskog sporazuma, kao i situacija na terenu.</p>\r\n<p>Dačić je dodao da ga je prijatno iznenadio govor &scaron;efice Unmika Karoline Zijade, jer je ona, kako je naveo, pobrojala nekoliko stvari koje su dovele do ove situacije.</p>\r\n<p>Kako je ocenio, sednica je imala nekoliko nivoa i ljudi treba da budu svesni da i pored na&scaron;eg nastojanja da se tema KiM drži stalno u fokusu SB, tj. UN, mnoge zemlje na Zapadu žele da se &scaron;to manje o tome govori.<br><br><a href=\"https://www.politika.rs/sr/clanak/598869/Orban-Srbija-sto-pre-mora-u-EU-ili-cemo-je-izgubiti)\"><img style=\"width: 212px; height: 120px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_Viktor-Orban--ANVAS156-a.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.politika.rs/sr/clanak/598869/Orban-Srbija-sto-pre-mora-u-EU-ili-cemo-je-izgubiti)\">Orban: Srbija &scaron;to pre mora u EU ili ćemo je izgubiti</a></span></h3>\r\n<p>&nbsp;</p>\r\n<p>Prema njegovim rečima, nekada su se te sednice održavale redovno na tri meseca i bile su četiri puta godi&scaron;nje, a sada ih ima samo dve i sa tog aspekta je veliki uspeh &scaron;to je uop&scaron;te održana ova poslednja sednica SB.</p>\r\n<p>Naglasio je da ovog puta nije ni održavano glasanje u SB o tome da li će sednica biti sazvana na zahtev Srbije, već je to Gvajana učinila sama, na &scaron;ta kao predsedavajuća ima pravo.</p>\r\n<p>On se zahvalio Gvajani, naglasiv&scaron;i da smo dobili novog prijatelja i navodeći da je, da nije bilo te zemlje, pitanje da li bi bilo sednice i da li bi ona bila otvorena za javnost. Istakao je da je održana sednica svakako velika diplomatska pobeda Srbije i dodao da čak i neki albanski analitičari sa KiM ukazuju da je Kurtijeva politika stalnog izazivanja incidenata dovela do toga da se KiM kao tema nađe u SB UN, i to u nekoj vrsti konflikta sa stavovima onih koji podržavaju njihovu nezavisnost. Dačić je dodao da je on tada odmah zvao (ministra spoljnih poslova Rusije Sergeja) Lavrova, koji mu se odmah javio na prvi poziv, &scaron;to je, kako je naglasio, velika stvar.</p>', 1, 'odobrena', '2024-02-12 01:11:50', 27, 0, 0, 33, 'images/vucic1.jpg'),
(136, 'VESIĆ TRAŽI DA SE ATLAS HRVATSKOG IZDAVAČA POVUČE IZ NAŠIH PRODAVNICA', '<p><strong>U pojedinim prodavnicama specijalizovanim za prodaju igračaka i dečije opreme prodaje se Dečji atlas sveta, hrvatskog izdavača, u kojem je&nbsp;<a href=\"https://www.kurir.rs/vesti/drustvo/3838585/skandalozno-vitorog-postavio-bilbord-sa-mapom-srbije-bez-kosova\" target=\"_blank\" rel=\"noopener\">Srbija prikazana bez Kosova i Metohije</a>.</strong></p>\r\n<p>Na ovo je upozorio i Goran Vesić, ministar građevinarstva, saobraćaja i infrastrukture, koji je na dru&scaron;tvenoj mreži Iks (biv&scaron;i Tviter) objavio slike ovog atlasa i rekao da je to neprihvatljivo.<br><br></p>\r\n<p style=\"text-align: center;\"><img src=\"https://www.kurir.rs/data/images/2024/02/12/11/3813967_screenshot-20240212111421871_ff.jpg?ver=1707733010\" alt=\"Goran Vesić\" width=\"455\" height=\"661\"></p>\r\n<p style=\"text-align: center;\">&nbsp;</p>\r\n<p>- Prijatelj mi je poslao slike Dečjeg atlasa sveta u izdanju hrvatskog izdavača koji se prodaje u radnjama u Beogradu.&nbsp;<strong>Srbija je u ovom atlasu prikazana kao država kojoj nedostaje 15 odsto teritorije!&nbsp;</strong>Ne ulazim u to da li se radi o previdu izdavača, Frojdovskoj oma&scaron;ci ili postupku sa predumi&scaron;ljajem, ali potpuno je neprihvatljivo da se ovakva knjiga prodaje u knjižarama usred Beograda.&nbsp;<strong>I to deci čija svest o sopstvenom narodu i državi treba tek da bude oblikovana</strong>&nbsp;- rekao je<a href=\"https://www.kurir.rs/vesti/politika/4352896/jacamo-saradnju-i-prijateljstvo-srbije-i-grcke-ministar-goran-vesic-ugostio-grckog-kolegu-hristosa-staikurasa\" target=\"_blank\" rel=\"noopener\">&nbsp;ministar</a>, zatraživ&scaron;i od nadležnih institucija da reaguju i da ova knjiga &scaron;to pre bude povučena iz prodaje.</p>\r\n<p>-&nbsp;<strong>Pitam se da li bi knjiga bilo kog srpskog izdavača koja osuđuje \"Oluju\" i proterivanje stotine hiljada Srba iz Hrvatske mogla da se prodaje deci u Zagrebu.</strong>&nbsp;Zato zahtevam od nadležnih institucija da reaguju i da ova knjiga &scaron;to pre bude povučena iz prodaje. Dečji atlas sam po sebi nije nikakav problem, naprotiv, zalažem se za to da deca &scaron;to vi&scaron;e čitaju i uče iz &scaron;tampanih knjiga, ali zadatak nadležnih je da im omoguće da uče iz knjiga koje po&scaron;tuju Ustav na&scaron;e zemlje i međunarodno pravo koji Srbiju tretiraju kao suverenu i celovitu državu - naveo je Vesić.</p>', 1, 'odobrena', '2024-02-12 01:17:09', 27, 1, 0, 1, 'images/vesic.jpg'),
(137, 'BORBA ZA OPSTANAK! Nepodnošljiv nam je dalji život u uslovima koje kreira Kurti! Autor Kurir Politika', '<p>Srbi s Kosova i Metohije okupiće se danas u Severnoj Mitrovici na velikom protestnom op&scaron;tenarodnom skupu, kojim žele da skrenu pažnju čitavom svetu i međunarodnoj zajednici na svoj obespravljen položaj. Neposredan povod za ovo je odluka Pri&scaron;tine i kosovskog premijera Aljbina Kurtija da ukinu dinar na ovoj teritoriji, čime se tamo&scaron;njim Srbima ugrožava ostanak i opstanak.</p>\r\n<p><strong>Ugroženi</strong></p>\r\n<p>Skup formalno organizuje Udruženje penzionera, koje ga je i prijavilo nadležnim organima. Odluka Pri&scaron;tine o zabrani upotrebe dinara u platnom prometu direktno pogađa zdravstvene i prosvetne radnike, socijalno ugrožene, studente... Iz Udruženja penzionera su poručili da će dana&scaron;nji miting biti \"zajednički mirni apel i skup da pokažemo celom svetu da vide na&scaron;u muku i obespravljenost\".</p>\r\n<p>Dana&scaron;nje okupljanje podržala je i Srpska lista. Predsednik Srpske liste Zlatan Elek kaže za Kurir da očekuje masovno okupljanje Srba s KiM, jer je odluka Pri&scaron;tine apsolutno neprihvatljiva, a dalji život nepodno&scaron;ljiv u uslovima koje kreira Kurti.</p>\r\n<p>&nbsp;</p>\r\n<figure><img style=\"width: 323px; height: 216px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/05/29/22/3476730_untitled1_ff.jpg?ver=1707660419\" alt=\"Zlatan Elek\">\r\n<figcaption></figcaption>\r\n</figure>\r\n<p>&nbsp;</p>\r\n<p>Od izuzetnog je značaja da svojim prisustvom u velikom broju pokažemo Pri&scaron;tini da se protivimo ovim antisrpskim odlukama i da želimo da u miru ostanemo da živimo na svojim vekovnim ognji&scaron;tima. Moraju se po&scaron;tovati međunarodno pravo i Rezolucija 1244. Pokazaćemo da Kurti nije u pravu kada uporno govori da je Kosovo demokratska država. Mi živimo u Srbiji, na okupiranoj teritoriji. Ustajemo protiv jednostranih poteza Pri&scaron;tine, od hap&scaron;enja na&scaron;ih nevinih sugrađana, militarizacije severa, pa sve do brutalnog upada kosovskih specijalaca u prostorije srpskih institucija, od privremenih organa pa do ambulanti, po&scaron;te i prostorija nevladinih organizacija. Naravno da ima rizika i opasnosti kada Srbi re&scaron;e da iskažu svoj protest. Sve policijske snage Pri&scaron;tina je prebacila na sever KiM. Živimo u getu i tako dalje ne može - poručuje Elek za Kurir.</p>\r\n<p>I načelnik odeljenja za plućne bolesti KBC Kosovska Mitrovica Milan Ivanović kaže za Kurir da je uveren da će protest biti masovan, jer nema nikoga na KiM ko nije pogođen represivnim Kurtijevim merama.</p>\r\n<p>&nbsp;</p>\r\n<figure><img style=\"width: 313px; height: 211px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2020/04/02/19/2189221_1006betaphoto-sasa-djordjevic_ff.jpg?ver=1707660440\" alt=\"Milan Ivanović\"></figure>\r\n<p>&nbsp;</p>\r\n<p>Nema sumnje da će Srbi zdu&scaron;no podržati izražavanje protesta. Osim psihičkog terora, sada nam Pri&scaron;tina udara direktno na egzistenciju. Moramo da se borimo. Srbija mora da se bori zajedno s nama, jer je ovo &scaron;to sprovodi Kurti najveće etničko či&scaron;ćenje na tlu Evrope. Dogorelo je do nokata i neko mora da stane na put ovim horor aktivnostima Pri&scaron;tine. Ugrožena su na&scaron;a vitalna prava i to će biti poruke ovog protesta - obja&scaron;njava na&scaron; sagovornik.</p>\r\n<p><strong>Narodno jedinstvo</strong></p>\r\n<p>Povodom aktuelne situacije na KiM oglasila se i Eparhija ra&scaron;ko-prizrenska, koja je apelovala na \"verni narod na Kosovu\" da pokaže dostojanstvo, hrabrost, snagu, narodno jedinstvo i trpljenje. U saop&scaron;tenju se upozorava da su Srbi izloženi otvorenoj represiji kosovskih vlasti kao nikada dosad od zavr&scaron;etka oružanog sukoba 1999. godine.</p>\r\n<p>&nbsp;</p>\r\n<figure><img style=\"width: 317px; height: 179px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2018/12/17/12/1709537_07_ff.jpg?ver=1707660498\" alt=\"spc, Eparhija Ra&scaron;ko-prizrenska, jubilej, Vladika Teodosije\">\r\n<figcaption></figcaption>\r\n</figure>\r\n<p>&nbsp;</p>\r\n<p>&nbsp;Duboko osećajući i proživljavajući stradanje na&scaron;eg naroda, koji nam se svakodnevno obraća za pomoć, upućujemo ovaj apel - ne kosovskim vlastima, jer očigledno nemaju spremnosti da stvore normalne uslove za život na&scaron;eg naroda i izgrade viziju dru&scaron;tva u kome bi svi ljudi bez obzira na etničko poreklo i veru živeli mirno i sigurno, niti međunarodnim predstavnicima, koji i pored zvaničnog stava da se svima mora omogućiti normalan i ravnopravan život, isuvi&scaron;e glasno toleri&scaron;u nasilje pri&scaron;tinskih vlasti, posebno kosovske policije, već samom na&scaron;em vernom narodu s kojim je SPC vekovima delila sve nevolje u toku osmanske okupacije, u vreme stradanja u Prvom i Drugom svetskom ratu, u vreme komunističke vlasti, kao i u toku svih novijih zbivanja, posebno od 1999. do danas - navodi se u saop&scaron;tenju.</p>\r\n<div>\r\n<div id=\"vjs_video_3\" tabindex=\"-1\" role=\"region\" translate=\"no\" aria-label=\"Video Player\"></div>\r\n</div>\r\n<div>\r\n<h2>Protest Srba ispred zgrade op&scaron;tine Zvečan</h2>\r\n<p><a href=\"https://www.kurir.rs/vesti/politika/4352931/borba-za-opstanak-poruka-srba-pred-danasnje-okupljanje-na-kim-nepodnosljiv-nam-je-dalji-zivot-u-uslovima-koje-kreira-kurti#:~:text=00%3A29,zgrade%20op%C5%A1tine%20Zve%C4%8Dan\">https://www.kurir.rs/vesti/politika/4352931/borba-za-opstanak-poruka-srba-pred-danasnje-okupljanje-na-kim-nepodnosljiv-nam-je-dalji-zivot-u-uslovima-koje-kreira-kurti#:~:text=00%3A29,zgrade%20op%C5%A1tine%20Zve%C4%8Dan</a></p>\r\n</div>', 1, 'odobrena', '2024-02-12 01:32:01', 27, 1, 1, 1, 'images/kosovo.jpg'),
(138, 'NOVAK BI MOGAO DA IGRA DO 55. GODINE\" Čuveni Britanci stali na Đokovićevu stranu', '<p>O porazu&nbsp;<a href=\"https://www.kurir.rs/tag/327/novak-dokovic\" data-taglink=\"Novak Đoković\">Novaka Đokovića</a>&nbsp;u Melburnu i dalje se priča, ima ljudi koji su jedva dočekali da srpskog tenisera već sada po&scaron;alju u \"penziju\", dok je vi&scaron;e onih koji veruju da će Nole jo&scaron; dugo biti na tronu.</p>\r\n<p>Među onima koji su pružili podr&scaron;ku srpskog teniseru na&scaron;li su se Britanci,&nbsp;<strong>Tim Henman&nbsp;</strong>i&nbsp;<strong>Lora Robson</strong>.</p>\r\n<div>&nbsp;</div>\r\n<p>Poznati Britanci su ubeđeni da će&nbsp;<strong>Đoković&nbsp;</strong>jo&scaron; dugo dominirati...</p>\r\n<p>-&nbsp;<strong>Znate kako, kada lestvicu postavite tako visoko, onda postoji samo jedan put posle toga. Sam je priznao posle polufinala u Melburnu da mu je to bio jedan od najgorih mečeva na slemovima.&nbsp;</strong>Ali kada osvojite taj turnir 10 puta, pričate o 100 mečeva, tako da je u ljudskoj prirodi da u jednom momentu dođe slabiji meč, nema potrebe za uključivanjem alarma. Za mene je on favorit na svakom turniru na kom bude igrao - ističe Henman.</p>\r\n<p>Lora Robson smatra da Novak može jo&scaron; mnogo godina da igra na vrhunskom nivou.</p>\r\n<p>- Za mene taj poraz od Sinera nije katastrofa, kao ni poraz od De Minora na početku godine, ne bih tome pridavala veliki značaj. Jo&scaron; uvek je najbolji na svetu, osvaja skoro sve. Jednostavno, mlađi igrači se probijaju, imaju sve vi&scaron;e samopouzdanja i veruju da mogu da ga izazovu u mečevima na tri dobijena seta, &scaron;to možda ranije nije bio slučaj. On ima 36 godina, kreće se fantastično i zaista nisam zabrinuta. Osećam da je on jedan od onih sportista koji bi mogao da igra do 55. godine - kazala je Lora.<br><br><br></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\">NE PROPUSTITE</span></h3>\r\n<div style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352939/preminuo-leni-simpson\"><img style=\"width: 203px; height: 203px;\" src=\"https://www.kurir.rs/data/images/2024/02/11/15/3813544_leni-simpson_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a></span>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352939/preminuo-leni-simpson\">TUGA U SVETU TENISA! Preminula legenda US Opena, igrač iz KUĆE SLAVNIH i veliki dobrotvor!</a></span></h2>\r\n</div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352905/gael-monfis-se-oglasio-posle-skandala-u-oslu\"><img style=\"width: 202px; height: 202px;\" src=\"https://www.kurir.rs/data/images/2020/02/17/12/2144851_aaa01-epa_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a></span>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352905/gael-monfis-se-oglasio-posle-skandala-u-oslu\">POVREDIO SUPERVIZORA, IZBAČEN SA TURNIRA, PA SE OGLASIO POSLE SKANDALA: \'Želim svima da kažem &scaron;ta se desilo...\'</a></span></h2>\r\n</div>\r\n<div style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352852/nadal-brusi-formu-pred-povratak-na-teren\"><img style=\"width: 175px; height: 175px;\" src=\"https://www.kurir.rs/data/images/2024/02/11/11/3813377_screenshot-6_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a></span>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/tenis/4352852/nadal-brusi-formu-pred-povratak-na-teren\">NADAL TRENIRA PUNOM PAROM! &Scaron;panac se sprema za povratak na teren, njegov NEOBIČAN trening privukao veliku pažnju!</a></span></h2>\r\n</div>\r\n<div style=\"text-align: center;\">&nbsp;</div>', 2, 'odobrena', '2024-02-12 04:58:56', 28, 1, 0, 34, 'images/novak.jpg'),
(139, 'MISLIMO SAMO NA MEČ S HRVATIMA!', '<p>Srpski vaterpolisti nao&scaron;treni da se u utorak revan&scaron;iraju Hrvatskoj za poraz u četvrtfinalu na pro&scaron;lom Svetskom prvenstvu.Hrvati su opravdali ulogu favorita i sa ubedljivih 22:4 sru&scaron;ili Kinu u osmini finala, te&nbsp;<a href=\"https://www.kurir.rs/sport/ostali-sportovi/4352958/selektor-hrvatske-srbija-je-sila-gigant\" target=\"_blank\" rel=\"noopener\">zakazali duel protiv na&scaron;e reprezentacije</a>.</p>\r\n<p>Četa Ivice Tucka dominirala je tokom čitavog meča i u utorak od 17 časova očekuje nas pravi spektakl u četvrtfinalu.</p>\r\n<div>&nbsp;</div>\r\n<p>Po&scaron;to smo se direktno plasirali u četvrtfinale, selektor Uro&scaron; Stevanović i njegovi momci imali su vi&scaron;e vremena za analizu i pripremu jo&scaron; jednog vaterpolo klasika.</p>\r\n<p><em>- Zavr&scaron;ili smo grupnu fazu na prvom mestu, &scaron;to nam je i bilo najbitnije, jer smo se kvalifikovali za Olimpijske igre. Grupa je bila izuzetno jaka i zbog toga sam srećan &scaron;to smo iz sva tri duela iza&scaron;li kao pobednici. U te tri jake utakmice smo podizali formu i verujem da ćemo tek biti pravi u narednim mečevima</em>&nbsp;- rekao je reprezentativac&nbsp;<strong><a href=\"https://www.kurir.rs/tag/263019/strahinja-rasovic\" data-taglink=\"Strahinja Ra&scaron;ović\">Strahinja Ra&scaron;ović</a></strong>&nbsp;i dodao:</p>\r\n<p>-&nbsp;<em>Spremamo se za Hrvatsku, imamo vremena za pripremu tog četvrtfinalnog duela. Ono &scaron;to je bilo ostavljamo iza sebe i okrenuti smo samo jednom meču.<br></em></p>\r\n<p>&nbsp;</p>\r\n<figure><img style=\"width: 397px; height: 276px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/07/19/07/3534968_srbijaaustralija22899_ff.jpg?ver=1707725952\" alt=\"Strahinja Ra&scaron;ović\">\r\n<figcaption></figcaption>\r\n</figure>\r\n<p>&nbsp;</p>\r\n<p>Nekoliko puta su Srbija i Hrvatska sparingovali uoči prethodnih &scaron;ampionata, poslednji zvaničan meč odigrali su na Svetskom prvenstvu u Budimpe&scaron;ti, kada su \"barakude\" trijumfovale u četvrtfinalu.</p>\r\n<p>Pred okr&scaron;aj ljutih rivala oglasio se jedan od najtrofejnijih trenera u istoriji ovog sporta, proslavljeni Hrvat Ratko Rudić (75). On ne želi da potceni Srbiju, ali ističe da na&scaron;a selekcija vi&scaron;e nije moćna kao ranije.</p>\r\n<p><em>- U ovom trenutku reprezentacija Srbije nije onakva kakva je bila ranije. Naravno, bez potcenjivanja. Hrvatska je bila dobra protiv Australije, dok sa &Scaron;panijom nije bila na očekivanom nivou. Utakmica sa Srbijom biće ona u kojoj ćemo videti koliko Hrvatska vredi</em>&nbsp;- poručio je Rudić.</p>\r\n<div>\r\n<div>\r\n<div>\r\n<h2>&nbsp;</h2>\r\n</div>\r\n</div>\r\n</div>', 2, 'odobrena', '2024-02-12 02:27:44', 28, 0, 0, 1, 'images/vaterpolo.jpg'),
(140, 'MAKSIMOVIĆ UŠAO U ISTORIJU HETAFEA! Poklon koji je dobio će pamtiti dugo!', '<p><a href=\"https://www.espreso.co.rs/tag/14174/nemanja-maksimovic\" data-taglink=\"Nemanja Maksimović\">Nemanja Maksimović</a>&nbsp;je posle perioda u<strong>&nbsp;Valensiji</strong>&nbsp;gde nikako nije uspeo da se dokaže, stigao u<strong>&nbsp;Hetafe</strong> 2018. godine i od tada ne mrda iz tog kluba.Jedan od najboljih veznih igrača tog kluba u poslednjih deset godina dokazuje se iz meča u meč, a koliko ga vole u tom klubu i koliko mu veruju dokazali su i u nedelju.</p>\r\n<p><strong>Nemanja</strong>&nbsp;je dobio prikladan poklon, dres sa brojem&nbsp;<strong>200,</strong>&nbsp;simbolično jer je upravo toliko utakmica odigrao u dresu ovog kluba, &scaron;to je zaista impresivna brojka.</p>\r\n<p><strong>Predsednik Anhel Tores mu je uručio dres.</strong></p>\r\n<div id=\"ctl00_Ams1_DocumentContent_nwsTags\"></div>\r\n<p><strong>Hetafe</strong>&nbsp;je uspeo da savlada&nbsp;<strong>Seltu</strong>&nbsp;u jučera&scaron;njem duelu rezultatom&nbsp;<strong>3:2</strong>, a Nemanja je bio starter na ovom meču.</p>\r\n<p>Valja napomenuti da je u periodu provedenom u<strong>&nbsp;Hetafeu Maksimović</strong>&nbsp;postigao sedam golova. Počeo je u mlađim kategorijama&nbsp;<strong>Crvene zvezde,</strong>&nbsp;igrao je za&nbsp;<strong>Domžale, Astanu i Valensiju.</strong></p>\r\n<p>Ima dve osvojene&nbsp;<strong>Premijer lige Kazahstana,</strong>&nbsp;kao i kup te države,<strong>&nbsp;a osvojio je U19 Evropsko prvenstvo sa Srbijom i dve godine kasnije Mundijalito na Novom Zelandu za igrače mlađe od 20 godina, upravo je on bio strelac pobedonosnog gola protiv Brazila u finalu.</strong></p>', 2, 'odobrena', '2024-02-12 02:41:48', 28, 1, 0, 1, 'images/fudbal.jpg'),
(141, 'REŠETAO MREŽE PA POKUPIO VREDNO PRIZNANJE! Vlahović je najbolji u Italiji - sada je i ZVANIČNO, surova DOMINACIJA srpskog napadača', '<p><a href=\"https://www.kurir.rs/tag/224985/dusan-vlahovic\" data-taglink=\"Du&scaron;an Vlahović\">Du&scaron;an Vlahović</a>&nbsp;ove godine fantastično igra u Seriji A, a sjajne partije nisu pro&scaron;le nezapaženo te je srpski reprezentativac postao vlasnik velikog priznanja.</p>\r\n<p>Naime, Vlahović je progla&scaron;en najboljim fudbalerom januara u Seriji A.</p>\r\n<p>Tokom meseca koji je iza nas, Vlahović se &scaron;est puta upisao u strelce dok je upisao i jednu asistenciju &scaron;to je bilo dovoljno da pokupi pomenuto priznanje.</p>\r\n<figure><img style=\"width: 429px; height: 286px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/01/28/09/3804356_profimedia0841105068_ff.jpg?ver=1707492310\" alt=\"Du&scaron;an Vlahović\">\r\n<figcaption></figcaption>\r\n</figure>\r\n<p>&bdquo;Du&scaron;an Vlahović je u mesecu januaru bio jednostavno savr&scaron;en&ldquo;, kazao je Luiđi De Siervo, izvr&scaron;ni direktor Serije A.</p>\r\n<p>&bdquo;Dao je gol na svakom od četiri meča u meseci, napadač &lsquo;bjankonera&rsquo; je dao &scaron;est golova ukupno, pokazao je svoj repertoar snage, vazdu&scaron;ne igre i osećaja za gol. Vlahović je sebe potvrdio kao kompletnog napadača, sposobnog da postiže golove na sve moguće načine i pomaže Juventusovoj trci za vrh tabele&ldquo;, dodao je De Siervo.</p>\r\n<p>&nbsp;</p>\r\n<div data-wdg=\"relwidget\">\r\n<h3 style=\"text-align: center;\">NE PROPUSTITE</h3>\r\n<div><a href=\"https://www.kurir.rs/sport/fudbal/4350633/besramna-izjava-legende-juventusa-vlahovic-i-milik-su-krivi-sto-inter-ima-cetiri-boda-vise-od-nas\"><img style=\"width: 165px; height: 165px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/12/01/12/3725086_vlahovic_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a>\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/sport/fudbal/4350633/besramna-izjava-legende-juventusa-vlahovic-i-milik-su-krivi-sto-inter-ima-cetiri-boda-vise-od-nas\">BESRAMNA IZJAVA LEGENDE JUVENTUSA: Vlahović i Milik su KRIVI &scaron;to Inter ima četiri boda vi&scaron;e od nas!</a></span></h2>\r\n</div>\r\n<div><a href=\"https://www.kurir.rs/sport/fudbal/4350554/malerozan-vikend-dusana-vlahovica\"><img style=\"width: 189px; height: 189px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/02/05/14/3809278_vlahovic_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a>\r\n<h2 style=\"text-align: center;\"><a href=\"https://www.kurir.rs/sport/fudbal/4350554/malerozan-vikend-dusana-vlahovica\"><span style=\"font-size: 12pt;\">MALEROZNI VIKEND DU&Scaron;ANA VLAHOVIĆA! Trener Juventusa ga PROZVAO posle poraza u derbiju, dan kasnije je stigla LO&Scaron;A VEST</span></a></h2>\r\n</div>\r\n<div>&nbsp;</div>\r\n</div>', 2, 'odobrena', '2024-02-12 02:50:30', 28, 0, 0, 1, 'images/vlahovic.jpg'),
(142, 'Policija u Novom Pazaru uhapsila dvojicu muškaraca, šok usledio čim su zavirili u reno', '<p>Pripadnici Ministarstva unutra&scaron;njih poslova u Novom Pazaru, u saradnji sa Upravom granične policije,&nbsp;<a href=\"https://www.kurir.rs/tag/36/hapsenje\" data-taglink=\"hap&scaron;enje\">uhapsili&nbsp;</a><strong>su N. J. (47) i T. V. (41) iz Subotice</strong>&nbsp;zbog postojanja osnova sumnje da su izvr&scaron;ili krivično delo neovla&scaron;ćena proizvodnja i stavljanje u promet opojnih droga.</p>\r\n<p>Policija je sinoć, u okolini Novog Pazara, u &bdquo;renou&ldquo; kojim je upravljao N. J. i u kojem je suvozač bio T. V.,&nbsp;<strong>prona&scaron;la vi&scaron;e od 200 grama heroina, sakrivenog u kesi od čipsa</strong>.</p>\r\n<div>&nbsp;</div>\r\n<p>Takođe, utvrđeno je da je N. J.&nbsp;<strong>vozio pod dejstvom opijata</strong>, pa će protiv njega biti podneta i odgovarajuća prekr&scaron;ajna prijava po Zakonu o bezbednosti saobraćaja na putevima.</p>\r\n<p>N. J. i T. V. je određeno zadržavanje do 48 časova nakon čega će, uz krivičnu prijavu, biti privedeni nadležnom tužila&scaron;tvu.<br><br></p>\r\n<h3>NE PROPUSTITE</h3>\r\n<div><a href=\"https://www.kurir.rs/crna-hronika/4353252/uhapsen-drzavljanin-srbije-u-bijelom-polju\"><img style=\"width: 287px; height: 287px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2021/04/11/16/2527905_shutterstock-417474538_sq-xs.jpg\" alt=\"\" loading=\"lazy\">\r\n<h2 style=\"text-align: center;\"><span style=\"font-size: 10pt;\">U CRNOJ GORI UHAP&Scaron;EN SRBIN SA INTERPOLOVE POTERNICE! \'Pao\' u Bijelom Polju, a zbog ovoga mu preti kazna i do 15 godina!</span></h2>\r\n</a></div>\r\n<div>&nbsp;</div>\r\n<div>&nbsp;</div>\r\n<div style=\"text-align: center;\"><a href=\"https://www.kurir.rs/crna-hronika/4353212/najnoviji-detalji-smrti-bebe-u-becu\"><img style=\"width: 280px; height: 280px;\" src=\"https://www.kurir.rs/data/images/2024/02/01/10/3806811_beba-hrvatska_sq-xs.jpg\" alt=\"\" loading=\"lazy\"></a>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://www.kurir.rs/crna-hronika/4353212/najnoviji-detalji-smrti-bebe-u-becu\">NAJNOVIJI DETALJI SMRTI SRPSKE BEBE U BEČU! Otac i majka iza re&scaron;etaka, evo kako su se SRAMNO branili roditelji iz pakla!</a></span></h2>\r\n</div>\r\n<div>&nbsp;</div>', 3, 'odobrena', '2024-02-12 03:01:53', 29, 0, 0, 1, 'images/heroin.jpg'),
(143, 'SRBIN UHAPŠEN U ŠVAJCARSKOJ ZBOG PUCNJAVE! Ispalio hice na stambenu zgradu, pa pobegao!', '<p>U petak uveče do&scaron;lo je do<strong>&nbsp;pucnjave u &scaron;vajcarskom gradu Dietikonu, nakon čega je policija uhapsila osumnjičenog Srbina (26) za&nbsp;<a href=\"https://www.kurir.rs/tag/419/pucnjava\" target=\"_blank\" rel=\"noopener\">pucnjavu</a>, a sa njim, uhap&scaron;en je i tridesetogodi&scaron;nji &Scaron;veđanin.</strong></p>\r\n<p><a href=\"https://www.kurir.rs/tag/397905/svajcarska-policija\" target=\"_blank\" rel=\"noopener\">&Scaron;vajcarska policija</a>&nbsp;obavila je uviđaj, a sve dostupne informacije objavili su u saop&scaron;tenju za medije.</p>\r\n<div>&nbsp;</div>\r\n<p>Kako se navodi, Srbin je pucao na stambenu zgradu u Dietikonu, dok Javno tužila&scaron;tvo u Cirihu i policija jo&scaron; uvek istražuju sve okolnosti pucnjave.</p>\r\n<p>- Povređenih na sreću nije bilo - naveli su.</p>\r\n<p>&Scaron;veđanin (30) koji je uhap&scaron;en zajedno sa Srbinom, nalazi se takođe iza re&scaron;etaka zato &scaron;to je&nbsp;<strong>kod obojice pronađeno oko pet kilograma marihuane.</strong></p>\r\n<p>Nakon saslu&scaron;anja, obojica mu&scaron;karaca privedeni su javnom tužila&scaron;tvu.</p>\r\n<p>&nbsp;</p>\r\n<ul>\r\n<li style=\"list-style-type: none;\">\r\n<div>\r\n<div>\r\n<div>\r\n<h2>&nbsp;</h2>\r\n</div>\r\n</div>\r\n</div>\r\n</li>\r\n<li style=\"list-style-type: none;\">\r\n<div>\r\n<div>\r\n<div><a href=\"https://adriamedia.tv/Kurir-televizija/Vecernji-dnevnik/a67224/VECERNJI-DNEVNIK-23.01.2024.html\" target=\"_blank\" rel=\"noopener\"><img style=\"width: 233px; height: 131px;\" src=\"https://adriamedia.tv/thumbnail/87744\" alt=\"VEČERNJI DNEVNIK 23.01.2024\"></a></div>\r\n<div>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://adriamedia.tv/Kurir-televizija/Vecernji-dnevnik/a67224/VECERNJI-DNEVNIK-23.01.2024.html\" target=\"_blank\" rel=\"noopener\">VEČERNJI DNEVNIK 23.01.2024</a></span></h2>\r\n</div>\r\n</div>\r\n</div>\r\n</li>\r\n<li style=\"list-style-type: none;\">\r\n<div>\r\n<div>\r\n<div><a href=\"https://adriamedia.tv/Kurir-televizija/Usijanje/a67206/USIJANJE-23.01.2024.html\" target=\"_blank\" rel=\"noopener\"><img style=\"width: 237px; height: 133px;\" src=\"https://adriamedia.tv/thumbnail/87743\" alt=\"USIJANJE 23.01.2024.\"></a></div>\r\n<div>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://adriamedia.tv/Kurir-televizija/Usijanje/a67206/USIJANJE-23.01.2024.html\" target=\"_blank\" rel=\"noopener\">USIJANJE 23.01.2024.</a></span></h2>\r\n<p>&nbsp;</p>\r\n</div>\r\n</div>\r\n</div>\r\n</li>\r\n<li style=\"list-style-type: none;\">\r\n<div>\r\n<div>\r\n<div><a href=\"https://adriamedia.tv/Vesti/a67220/Organska-proizvodnja-Preljina-gazdinstvo-Marjanovic.html\" target=\"_blank\" rel=\"noopener\"><img style=\"width: 244px; height: 137px;\" src=\"https://adriamedia.tv/thumbnail/87736\" alt=\"Organska proizvodnja Preljina, gazdinstvo Marjanović\"></a></div>\r\n<div>\r\n<h2><span style=\"font-size: 12pt;\"><a href=\"https://adriamedia.tv/Vesti/a67220/Organska-proizvodnja-Preljina-gazdinstvo-Marjanovic.html\" target=\"_blank\" rel=\"noopener\">Organska proizvodnja Preljina, gazdinstvo Marjanović</a></span></h2>\r\n</div>\r\n</div>\r\n</div>\r\n</li>\r\n</ul>', 3, 'odobrena', '2024-02-08 03:10:18', 29, 0, 0, 36, 'images/hapsenje.jpg'),
(144, 'OVDE SU DVOJICA IZREŠETANA PO NOGAMA! Pucnjava probudila komšiluk: Mislili smo da nam neko kuca, a onda smo čuli policiju (FOTO)', '<p>U beogradskom naselju Zvezdara je, u nedelju oko 20 minuta posle ponoći do&scaron;lo do<a href=\"https://www.kurir.rs/crna-hronika/4347438/detalji-pucnjave-u-beogradu-potera-za-napadacem\" target=\"_blank\" rel=\"noopener\">&nbsp;pucnjave u kojoj su ranjena dvojica mu&scaron;karaca</a>.</p>\r\n<p>Kako Kurir nezvanično saznaje pucao mu&scaron;karac star 43 godine&nbsp;<strong>upucao je u noge L.T. (30) i U. U. (40)</strong>. Policija i dalje traga za napadačem koji je identifikovan, ali se nalazi u bekstvu. Kako saznajemo, sva trojica mu&scaron;karaca su prethodno sedeli i pili zajedno, a potom je izbila svađa koja je dobela do obračuna.</p>\r\n<div>&nbsp;</div>\r\n<p>- Napadač im je tada pucao u noge. Ranjeni su prevezeni u Urgentni centar i imaju lak&scaron;e telesne povrede - kaže izvor Kurira.</p>\r\n<figure><img style=\"width: 485px; height: 364px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/01/28/12/3804441_whatsapp-image-20240128-at-12.24.46-pm-1_ff.jpg?ver=1706441718\" alt=\"Zvezdara, Pucnjava\">\r\n<figcaption>FOTO: KURIR</figcaption>\r\n</figure>\r\n<p>Prema informacijama sa lica mesta,&nbsp;<a href=\"https://www.kurir.rs/crna-hronika/4347416/pucnjava-u-beograduna-zvezdari\" target=\"_blank\" rel=\"noopener\">pucnjava je probudila kom&scaron;iluk</a>, ali niko nije čuo svađu, niti poznaje učesnike u obračunu.</p>\r\n<p>- Spavali smo, ovde uglavnom žive porodični ljudi sa decom. Tad sam čuo ne&scaron;to i pomislio da nam neko kuca, oti&scaron;ao sam do vrata, ali nikoga nije bilo - kaže jedan kom&scaron;ija za Kurir i dodaje:</p>\r\n<p>-&nbsp;<strong>Posle par minuta čuo sam policiju, pogledao kroz prozor i video da se ne&scaron;to de&scaron;ava</strong>. Tad smo shvatili da nije niko kucao, nego da je bilo vatrenog obračuna.</p>\r\n<div>\r\n<div>\r\n<div><a href=\"https://www.kurir.rs/crna-hronika/4347500/prve-slike-posle-pucnjave-na-zvezdari-komsije-u-soku-mislili-smo-da-nam-neko-kuca-a-onda-smo-culi-policiju-i-hitnu-pomoc/media/76210\"><img style=\"width: 443px; height: 332px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/01/28/12/3804444_whatsapp-image-20240128-at-12.24.41-pm_ff.jpg\"></a></div>\r\n<div>&nbsp;</div>\r\n</div>\r\n<div>\r\n<div>&nbsp;</div>\r\n</div>\r\n</div>\r\n<p>Kako nam je ispričala jedna kom&scaron;inica svađu niko nije čuo jer se verovatno odigrala na potpuno drugom mestu.</p>\r\n<p>- Ovde nema kafana, proslava, miran je deo grada i onda jedino da su bili u nekoj kući, ali zaista ne poznajemo nikoga ko bi mogao ovako ne&scaron;to da uradi - kaže ona.</p>\r\n<p>Prema njenim rečima, kom&scaron;ije pretpostavljaju da su se oni samo dovezli u zabačeni deo ulice i da je tu problem eskalirao.</p>\r\n<p>- S obzoirom da se sve desilo na uglu sa jo&scaron; jednom sporednom uličicom na delu gde ima manje kuća,<strong>&nbsp;pretpostavljamo da su se tu dovezli nakadno</strong>. Čudno nam je da ne poznajemo nikoga, a o napadaču niko ni govori - kaže kom&scaron;inica i dodaje:</p>\r\n<p>- Strah nas je jer je u bekstvu, ali mislimo da se ovamo neće vraćati, na mesto zločina.</p>\r\n<p>L.T. i U.U. su zbrinuti i oni nisu ni u kakvoj životnoj opasnosti, a napadač će po hap&scaron;enju biti zadržan, a zatim priveden u Vi&scaron;e javno tužila&scaron;tvo u Beogradu na</p>', 3, 'odobrena', '2024-02-12 03:10:19', 29, 0, 0, 36, 'images/pucnjava.jpg'),
(145, 'UŠAO U KASARNU, PA KRENUO DA PUCA PO VOJNICIMA KOJI SU SPAVALI: Užas u Iranu, ima mrtvih', '<p>Iranski vojnik je danas u jugoističnom gradu Kermanu&nbsp;<strong>otvorio vatru na druge vojnike</strong>, ubiv&scaron;i tom prilikom petoro njih, saop&scaron;tila je iranska državna televizija.</p>\r\n<p>U izve&scaron;taju iranske televizije se navodi da je do pucnjave do&scaron;lo kada je vojnik u&scaron;ao u kasarnu i počeo da puca na druge vojnike koji su spavali.</p>\r\n<div>&nbsp;</div>\r\n<p>Dodaje se da&nbsp;<strong>nije poznat motiv napada</strong>&nbsp;a počinilac, čiji identitet nije saop&scaron;ten se nalazi u bekstvu.</p>\r\n<p>U izve&scaron;taju je rečeno da je do incidenta do&scaron;lo u gradu Kermanu, koji se nalazi na oko 830 kilometara od glavnog grada Teherana.</p>\r\n<p><a href=\"https://www.kurir.rs/planeta/4330546/raste-broj-zrtava-masakra-u-iranu-saopsteno-koliko-ih-ima-za-sada-strahuje-se-da-ce-ih-biti-vise\" target=\"_blank\" rel=\"noopener\">Kerman je bio popri&scaron;te dve smrtonosne eksplozije ranije ovog meseca</a>&nbsp;u kojima su poginule 94 osobe i ranjene stotine drugih tokom ceremonije obeležavanja godi&scaron;njice smrti iranskog generala ubijenog u napadu američkih bespilotnih letelica u Iraku 2020. godine.</p>\r\n<p>Odgovornost za taj napad je preuzela grupa Islamska država.</p>\r\n<p>Slične pucnjave u vojnim bazama su relativno česte u Iranu. 2022. godine, vojnik je ubio jo&scaron; jednog vojnika i tri policajca u policijskoj stanici pored puta na jugu zemlje.</p>\r\n<p>U Iranu je vojna služba do 24 meseca obavezna za mu&scaron;karce od 19 i vi&scaron;e godina.</p>', 3, 'odobrena', '2024-02-12 03:10:17', 29, 0, 0, 36, 'images/iran.jpg'),
(146, 'VODITELJKA DNEVNIKA TAJNO LJUBILA OVOG FUDBALERA A onda se sve saznalo', '<p>U vezi su bili 2015. godine, a ljubav su na sve načine poku&scaron;avali da sakriju od očiju javnosti.</p>\r\n<p>Za emisiju \"Premijera\" Savo je tada i otkrio čime ga je Maja osvojila:</p>\r\n<p>- Maja mi se dopala čim sam je ugledao. Sedeli smo u istom dru&scaron;tvu, i kako nisam znao ko je ona, morao sam da se raspitujem, tražio sam je po Jutjubu - rekao je tada.</p>\r\n<figure style=\"text-align: center;\">\r\n<div style=\"text-align: center;\">\r\n<figure><picture><source srcset=\"//ocdn.eu/pulscms-transforms/1/yGXk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwBQ\" type=\"image/webp\" data-original-image=\"//ocdn.eu/pulscms-transforms/1/yGXk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwBQ\" data-srcset=\"//ocdn.eu/pulscms-transforms/1/yGXk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwBQ\"><img style=\"width: 414px; height: 276px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://ocdn.eu/pulscms-transforms/1/9nqk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwAQ\" alt=\"Savo Milo&scaron;ević\" width=\"1200\" height=\"800\" data-original-image=\"//ocdn.eu/pulscms-transforms/1/9nqk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwAQ\" data-src=\"//ocdn.eu/pulscms-transforms/1/9nqk9kqTURBXy9kNjI3OTBjM2U0Mjc4ZGQ1YTU5YjM0OTU0YTk3NWRkZi5qcGVnkZMCzQSwAN4AAaEwAQ\"></picture></figure>\r\nFOTO: ALEKSANDAR DIMITRIJEVIĆ / RAS SRBIJA</div>\r\n<figcaption>Savo Milo&scaron;ević</figcaption>\r\n</figure>\r\n<div data-placeholder-caption=\"Oglas\">\r\n<div>\r\n<div id=\"InText_2\" data-google-query-id=\"CJ2x-92LpoQDFSj6EQgd-RYM4w\">\r\n<div id=\"google_ads_iframe_/161634325/Blic.rs/InText_2_0__container__\"></div>\r\n</div>\r\n</div>\r\n</div>\r\n<p>Ipak, do raskida je do&scaron;lo nakon svega nekoliko meseci, a voditeljka je danas srećno zaljubljena u svog novog partnera kog nije prikazala javnosti.</p>\r\n<p>Da podsetimo, voditeljka Maja Manojlović u emisiji \"Magazin In\" nedavno je&nbsp;<a id=\"a4172b4c-5bf4-4947-8941-06b3bdb88bd7\" href=\"https://www.blic.rs/zabava/moja-majka-je-vise-volela-supruga-nego-decu-voditeljka-iznela-porodicne-detalje/wgc48eh\">pričala o očuvanju braka.</a></p>\r\n<p>- Moji roditelji su bili u vrlo srećnom i lepom braku dugom 37 godina. Moja majka je do kraja svog života najvi&scaron;e volela svog muža. To nam je rekla i na samrti, meni i mom bratu, započela je voditeljka u \"Magazin in\", zbog čega je i sama bila iznenađena:</p>\r\n<p>- Ja sam kasnije oti&scaron;la pod Ostrog i razgovarala sam sa duhovnikom i upitala sam ga \'\'Kako je moguće da je moja majka rekla da je vi&scaron;e volela svog muža nego svoju decu\'\'? On mi je rekao \'\'Pa to je sasvim normalno. Voli se Bog, pa se voli muž, jer on je njoj dao decu, pa se vole deca, jer deca dođu i vi ih iznederite i oni odu iz va&scaron;eg života\'\'. Tada sam shvatila poentu! Nema, dakle griže savesti u smislu zapostavljanja dece, ako si okrenuta suprugu, rekala je&nbsp;<a id=\"5ae8a985-ae1a-47a9-b0a0-1cc85168d714\" href=\"https://www.blic.rs/maja-manojlovic\">Maja Manojlović.</a></p>', 4, 'odobrena', '2024-02-11 03:23:26', 30, 0, 0, 35, 'images/voditeljka3.jpg'),
(147, '\"RODILA SE NINA\" Aleksandra Nikolić podelila srećne vesti, objavila TRENUTAK SA SLAVLJA', '<p>Biv&scaron;a rijaliti učesnica Aleksandra Nikolić, koja je u drugom stanju sa Filipom Carem, podelila je srećne vesti.</p>\r\n<p>Pobednica \"Zadruge\" je u 31. nedelji trudnoće, a <a id=\"2286c795-c73a-464a-982d-6f22204ccf24\" href=\"https://www.blic.rs/zabava/aleksandra-nikolic-pred-porodaj-uputila-molbu-dobila-sam-hipotireozu/k0tlcfq\">nedavno je otkrila sa kakvim se zdravstvenim problemom bori.</a></p>\r\n<p>- Zamolila bih ljude koji me podržavaju da mi ne &scaron;alju apsolutno ni&scaron;ta vezano za neke druge osobe iz sveta rijalitija jer me zaista ni&scaron;ta ne zanima. Kao &scaron;to znate na TikToku vi&scaron;e nisam, odmaram se od svega.</p>\r\n<p>Zbog stresnog života i prevelikog pritiska javnosti, nažalost, dobila sam hipotireozu i terapiju koju ću verovatno jako dugo piti, tako da me zaista ni&scaron;ta od toga ne interesuje. Isključivo lepe stvari dolaze u obzir. Čuvajte sebe i volite sebe i svoje zdravlje stavite na prvo mesto!</p>', 4, 'odobrena', '2024-02-12 03:23:25', 30, 0, 0, 35, 'images/nikolic.jpg'),
(148, 'NAJVEĆI SKANDAL PRINCA HARIJA I DANAS TRESE JAVNOST: Sa 20 godina uradio NEZAMISLIVU stvar, pa za sve okrivio BRATA I SNAJKU', '<p><strong><a href=\"https://www.kurir.rs/tag/473749/princ-hari\" target=\"_blank\" rel=\"noopener\">Princ Hari</a>&nbsp;je imao 20 godina kada je britanski The Sun objavio njegovu fotografiju na naslovnoj strani u nacističkoj uniformi i sa velikim crvenim kukastim krstom</strong>. Princ Hari&nbsp;<strong>poznat je po brojnim skandalima</strong>&nbsp;kojima je osramotio kraljevsku porodicu, a jo&scaron; se pamti i ovaj čuveni incident 2005. godine.</p>\r\n<p>Princ Hari je imao 20 godina kada je britanski list The Sun objavio njegovu fotografiju na naslovnoj strani u nacističkoj uniformi i sa velikim crvenim kukastim krstom.&nbsp;<strong>Princ je tu uniformu odabrao za kostimografiju, čija je tema bila \"domorodci i kolonije\".</strong></p>\r\n<div>&nbsp;</div>\r\n<div>\r\n<div><iframe id=\"twitter-widget-0\" style=\"width: 457px; height: 227px; display: table; margin-left: auto; margin-right: auto;\" title=\"X Post\" src=\"https://platform.twitter.com/embed/Tweet.html?creatorScreenName=KurirVesti&amp;dnt=false&amp;embedId=twitter-widget-0&amp;%3D%3D&amp;frame=false&amp;hideCard=false&amp;hideThread=false&amp;id=1610867578251145217&amp;lang=sr&amp;origin=https%3A%2F%2Fwww.kurir.rs%2Fzabava%2Fpop-kultura%2F4353033%2Fprinc-hari-u-nacisticlkoj-uniformi&amp;sessionId=6e526343f5a3b97299ae39b380e6d4709fedabca&amp;siteScreenName=KurirVesti&amp;theme=light&amp;widgetsVersion=2615f7e52b7e0%3A1702314776716&amp;width=550px\" width=\"457\" height=\"227\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\" data-tweet-id=\"1610867578251145217\"></iframe></div>\r\n</div>\r\n<p>-&nbsp;<strong>To je verovatno bila jedna od najvećih gre&scaron;aka u mom životu</strong>. Bilo me je tako sramota nakon toga - rekao je u dokumentarcu \"Hari i Megan\".</p>\r\n<p>On je u&nbsp;<a href=\"https://www.kurir.rs/zabava/pop-kultura/4094604/ovako-je-carls-saopstio-hariju-da-mu-je-majka-poginula\" target=\"_blank\" rel=\"noopener\">svojoj knjizi \"Spare\"</a>&nbsp;napisao da su glavni krivci za sve njegov brat,&nbsp;<strong>princ Vilijam i snaja Kejt Midlton, koji su takođe bili na toj kostimografskoj zabavi.&nbsp;</strong>U jednom delu knjige Hari je otkrio da je bio rastrgan između nacističke i pilotske uniforme.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 434px; height: 571px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/02/11/21/3813699_profimedia0073524791_ff.jpg?ver=1707682234\" alt=\"Princ Hari\">\r\n<figcaption>FOTO: PROFIMEDIA</figcaption>\r\n</figure>\r\n<p>- Pozvao sam Vilija i Kejt i pitao ih &scaron;ta misle, a<strong>&nbsp;oni su mi rekli da treba da nosim nacističku uniformu</strong>&nbsp;- napisao je on i dodao da ju je potom isprobao pred njima i da su bili odu&scaron;evljeni.</p>\r\n<p>Navodno je zbog njihovog entuzijazma odabrao nacističku uniformu.&nbsp;<strong>Inače, Vilijam je na toj zabavi nosio kostim lava domaće izrade.</strong></p>', 4, 'odobrena', '2024-02-12 03:29:18', 30, 0, 0, 1, 'images/princ.jpg'),
(149, '\"SAD ZNAMO KOGA JE ZANIMALA BOJA KOŽE SINA MEGAN MARKL\" Jedna rečenica odala omiljeno NEVINAŠCE na dvoru i sad je NA STUBU SRAMA', '<p>Nakon vesti o tome da njegov otac,&nbsp;<strong><a href=\"https://www.kurir.rs/zabava/pop-kultura/4350681/kralju-carlsu-dijagnostifikovan-rak\" target=\"_blank\" rel=\"noopener\">kralj Čarls III, ima karcinom</a></strong>, te da je iz Londona helikopterom prevezen u Norfolk, gde će boraviti,&nbsp;<strong><a href=\"https://www.kurir.rs/tag/487249/princ-vilijam\" target=\"_blank\" rel=\"noopener\">princ Vilijam</a></strong>&nbsp;je preuzeo deo njegovih dužnosti, a u javnosti se pojavio nekoliko puta poslednjih dana.</p>\r\n<p>Kako je naglasio na gala večeri u Londonu, zahvalan je na svoj podr&scaron;ci koju porodica dobija nakon Čarlsove dijagnoze, kao i&nbsp;<strong>nakon abdominalne operacije</strong>&nbsp;njegove supruge Ketrin Midlton.</p>\r\n<div>&nbsp;</div>\r\n<figure style=\"text-align: center;\"><img style=\"width: 486px; height: 347px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/11/17/19/3704056_profimedia0822677696_ff.jpg?ver=1707565880\" alt=\"princ Vilijam\">\r\n<figcaption>FOTO: ANTHONY DEVLIN-GETTY/POOL SUPPLIED BY SPLASH NEWS / SPLASHNEWS.COM / SPLASH / PROFIMEDIA</figcaption>\r\n</figure>\r\n<p>-To nam mnogo znači - ispričao je on.</p>\r\n<p>- Moram da kažem da su poslednje sedmice imale prilično medicinski fokus za nas, pa sam do&scaron;ao ovde da pobegnem od toga - rekao je on.</p>\r\n<p>Vilijam je, između ostalog, dospeo i na stub srama zbog rečenica koje je izgovorio povodom Kejtine bolesti, a korisnicima dru&scaron;tvenih mreža se jedan detalj posebno nije dopao.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 433px; height: 301px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/05/09/18/3453352_kejt-midlton-princ-vilijam-profimedia0774689759_ff.jpg?ver=1707565894\" alt=\"Kejt Midlton, princ Vilijam\">\r\n<figcaption>FOTO: BACKGRID / BACKGRID UK / PROFIMEDIA</figcaption>\r\n</figure>\r\n<p>To je uradio pre nekoliko dana na dodeli ordenja britanskog kraljevstva, a navodi se da je rekao da \"Ketrin ima dve filipinske medicinske sestre koje brinu o njoj\", kao i da su \"divne i ljubazne\".</p>\r\n<p>Zapravo, mnogima se nije dopao etnički momenat, odnosno&nbsp;<strong>to &scaron;to je Vilijam naglasio njihovo poreklo.</strong></p>\r\n<p>&nbsp;</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 454px; height: 303px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2022/07/13/07/3098435_profimedia0706073762_ff.jpg?ver=1707566007\" alt=\"Princ Vilijam\">\r\n<figcaption>FOTO: PROFIMEDIA<br><br></figcaption>\r\n</figure>\r\n<p>\"Kakve veze ima odakle su\", \"Ba&scaron; je važno da znamo da su njene bolničarke s Filipina. Za&scaron;to\", \"U sobi punoj belaca je njihovu rasu doveo u prvi plan\", \"Ovo nam govori ko je bio uključen u debatu o boji Arčijeve kože\", samo su neki od komentara korisnika dru&scaron;tvene mreže Iks (biv&scaron;i Tviter).</p>\r\n<p>&nbsp;</p>', 4, 'odobrena', '2024-02-12 03:31:18', 30, 0, 0, 1, 'images/megan.jpg');
INSERT INTO `vest` (`id_vesti`, `naslov`, `sadrzaj`, `id_rubrike`, `status`, `datum_vreme_objave`, `id_novinara`, `broj_pozitivnih`, `broj_negativnih`, `id_urednika`, `lead_slika_url`) VALUES
(150, 'LUKASA I SONJU UHVATILA KAKO SE LJUBE, SKANDAL SA POLICIJOM... Svi šok detalji iz života Danijele Vranić, a ona joj je bila BAKA', '<p><a href=\"https://www.kurir.rs/tag/1284/danijela-vranic\" target=\"_blank\" rel=\"noopener\">Danijela Vranić</a>&nbsp;se na estradnoj sceni pojavila 2006. godine, preko noći je očarala publiku atraktivnim izgledom, temperamentnim nastupom i brojnim hitovima, godinama kasnije ponela je titulu &bdquo;<strong>kraljica splavova&ldquo;</strong>, i onda netragom nestala.</p>\r\n<p>Ipak, ekipa Kurira je uspela da pronađe pevačicu, koja se posle vi&scaron;e od deset godina pojavila u javnosti.<a href=\"https://www.kurir.rs/stars/4353305/eksluzivni-paparaco-kurir-uhvatio-danijelu-vranic-ovako-izgleda-posle-10-godina-pauze-a-on-joj-pravi-drustvo-video\" target=\"_blank\" rel=\"noopener\">&nbsp;Sudeći po fotografijama koje je Kurir paparaco uslikao,</a>&nbsp;mogli smo da primetimo da se uop&scaron;te nije promenila i gotovo da je ista kao kada smo je poslednji put sreli.</p>\r\n<div>&nbsp;</div>\r\n<p><strong>Najveća ljubav joj je bio Aca Lukas</strong></p>\r\n<p>Danijela Vranić u vreme svoje velike popularnosti privlačila je veliku pažnju javnosti, a česta tema medija bila je njena veza sa Acom Lukasom.Kako se spekulisalo poslednjih godina, Danijeli je raskid veoma te&scaron;ko pao.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 464px; height: 310px;\" src=\"https://www.kurir.rs/data/images/2022/12/05/16/3273918_untitled5_ff.jpg?ver=1707748754\" alt=\"Aca Lukas, Danijela Vranić\">\r\n<figcaption>FOTO: DAMIR DERVI&Scaron;AGIĆ, NENAD KOSTIĆ</figcaption>\r\n</figure>\r\n<p>Lukas nikada nije krio da je bio veoma blizak sa Danijelom, a o detaljima njihove veze pisao je i u svojoj knjizi, gde je otkrio koliko mu je značila.</p>\r\n<p>- Danijela je prava diva, žena sa stilom. Sigurno jedna od na&scaron;ih najboljih pevačica. Za&scaron;to nije uspela? Vi&scaron;e je volela da sedi u kući i čeka da se ne&scaron;to dogodi bez njenog uče&scaron;ća. A to je nemoguće. Stvorila je nerealnu sliku o sebi, pa je doživela da uspeju mnogo lo&scaron;ije pevačice od nje - naveo je Lukas u knjizi \"Ovo sam ja\", a onda otkrio da je Sonja bila razlog njihovog raskida.</p>\r\n<p>- U trenu sam se zaljubio u Sonju, koja je poku&scaron;ala od mene da napravi namirisanu pudlicu. Stezala me je i gu&scaron;ila, a &scaron;to je najgore, meni se to svidelo - pi&scaron;e u njegovoj biografiji, u kojoj dalje navodi da mu je Željko tada rekao da se razvodi.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 467px; height: 312px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2021/06/23/14/2618679_danijela-vranic-aca-lukas-sonja-vuksanovic_ff.jpg?ver=1707748852\" alt=\"Aca Lukas, Sonja Vuksanović, Danijela Vranić\">\r\n<figcaption>FOTO: DAMIR DERVI&Scaron;AGIĆ, DRAGANA UDOVIČIĆ, NEMANJA NIKOLIĆ</figcaption>\r\n</figure>\r\n<p>- Ne sećam se kako sam dobio broj Sonjinog telefona. Poslao sam joj poruku. Uoči, po mnogo čemu, kobnog susreta sa Sonjom u Budvi, bio sam s Danijelom Vranić u vezi pred pucanjem. Krenuli smo na rođendansku žurku u Budvu, u&scaron;li smo u avion, a iza nas su bile Sonja i drugarica. Nisam se javio da Danijelu ne bih izlagao neprijatnosti. Primetila je da tu ima ne&scaron;to, pa je počela da ljubomori&scaron;e. Kad smo seli u taksi, bacila je sa sebe ogrlicu od 18.000 evra koju sam joj kupio. Rekao sam: \"Ne treba mi\" i bacio sam kroz prozor, kraj žbunja - prisećao se Lukas.</p>\r\n<p>- Na žurki sam se zverski napio i Sonja je. Ali znam da smo se posle nekoliko minuta ljubili iza kuće kao dva napaljena klinca. Pojavljuje se Danijela i u prolazu dobacuje: \"&Scaron;ta je, hoće&scaron; da j**** ne&scaron;to?\" Samo sam je pogledao i nastavio da se ljubim sa Sonjom. Danijela je oti&scaron;la u sobu. Nisam joj se javio. Dripački potez. Ružan kraj veze sa ženom koja to nije zaslužila - pi&scaron;e u knjizi.</p>\r\n<p>- U Beograd sam se vratio sa Sonjom krvavo zaljubljen. Venčali smo se u Crkvi Svetog Vasilija Ostro&scaron;kog. Posle smo s gostima oti&scaron;li u restoran. Sve je bilo kao u bajci. A onda se rodila Viktorija, moje mezimče - zavr&scaron;io je Lukas.</p>\r\n<p><strong>Skandal sa policijom</strong></p>\r\n<p>Tužila&scaron;tvo u Beogradu pre nekoliko godina&nbsp;<a href=\"https://www.kurir.rs/stars/3490143/poznati-zavrsili-u-zatvoru-zbog-kradje-droge-alkohola-ovo-su-vip-robijasi\" target=\"_blank\" rel=\"noopener\">podiglo je optužnicu protiv Danijele Vranić zbog napada na policajca</a>&nbsp;tokom privođenja u centru Beograda, kad je sa<strong>&nbsp;1,84 promila alkohola u krvi pravila darmar</strong>&nbsp;po centru grada bežeći od patrole. Pevačica je nakon suđenja morala da plati popriličnu sumu od&scaron;tete, ali je zatvor izbegla. Provela je samo jednu noć u ćeliji na trežnjenju.</p>\r\n<p><strong>Zanimljiv podatak iz biografije Danijele Vranić je da joj je čuvena proročica Vanga bila baba.</strong></p>\r\n<p>- Čuvala je sestru i mene kad smo bile male, ali se ne sećam mnogo toga. Za nas je bila samo na&scaron;a baka i ni&scaron;ta vi&scaron;e. Gajimo samo ljubav prema njoj i ponosna sam na nju kao na baku, a ne kao proročicu &ndash; ispričala je jednom prilikom.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 464px; height: 310px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2023/02/02/20/3339868_untitled2_ff.jpg?ver=1707748797\" alt=\"Baba Vanga\">\r\n<figcaption>FOTO: YOUTUBE/PRINTSCREEN, SHUTTERSTOCK</figcaption>\r\n</figure>\r\n<p>- Tatu sam stalno zapitkivala da mi kaže da li je možda baka ne&scaron;to rekla za nas, a on nam je u &scaron;ali uvek govorio samo to da ćemo moja sestra i ja biti srećne. Zapravo, mi i jesmo srećne. Inače, tata je taj koji je pobijao sve &scaron;to je baka govorila i nije verovao iako je ona pogađala. Svakako o njoj ne pričamo kao o</p>', 5, 'odobrena', '2024-02-11 03:45:09', 31, 0, 0, 37, 'images/sonja.jpg'),
(151, 'SVE DEVOJČICE SU BILE ZALJUBLJENE U NJEGA: Oženio se 10 godina STARIJOM PROFESORKOM! Bio na Farmi pa nestao iz javnosti...', '<p><a href=\"https://www.kurir.rs/tag/15488/nikola-saric-sajko\" data-taglink=\"Nikola Sarić Sajko\">Nikola Sarić Sajko</a>&nbsp;bio je jedan od najistaknutijih učesnika muzičkog takmičenja \"<a href=\"https://www.kurir.rs/tag/602019/operacija-trijumf\" data-taglink=\"Operacija trijumf\">Operacija trijumf</a>\", koje se emitovalo 2008. godine, a nakon dve godine u&scaron;ao je u rijaliti \"Farma\".</p>\r\n<p>Nikola je jo&scaron; tokom takmičenja stekao veliku pažnju pripadnica lep&scaron;eg pola, a broj njegovh<strong>&nbsp;fanova samo se povećao po ulasku u rijaliti.&nbsp;</strong>Nikola se po zavr&scaron;etku takmičenja jo&scaron; neko vreme bavio pevanjem, nakon čega je učestvovao u rijalitiju \"Farma 2\", a potom se potpuno povukao iz javnog života.</p>\r\n<div>&nbsp;</div>\r\n<figure style=\"text-align: center;\"><img style=\"width: 431px; height: 291px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2022/08/16/12/3134615_sajko_ff.jpg?ver=1707736157\" alt=\"Nikola Sarić Sajko\">\r\n<figcaption>FOTO: PRINTSCREEN YOUTUBE</figcaption>\r\n</figure>\r\n<p>Sajko je tada odlučio da se posveti ugostiteljstvu, pa je sa prijateljem otvorio kafić, a kada su razradili biznis, otvorili su jo&scaron; dva lokala.</p>\r\n<p>-&nbsp;<a href=\"https://www.kurir.rs/stars/3000135/foto-sve-devojcice-su-bile-zaljubljene-u-njega-evo-gde-je-danas-i-sta-radi-sajko-iz-operacije-trijumf\" target=\"_blank\" rel=\"noopener\">Krenuo sam da držim jedan kafić sa drugarom</a>, pa drugi i sada treći, koji je vi&scaron;e klub i shvatio sam da mi je to isplativije nego muzika - rekao je pre nekoliko godina Sajko, a potom dodao:</p>\r\n<p>- Moj život izgleda kafanski i svirački van medija. Sviram ba&scaron; često, ali ne pevam. Tako mi odgovara, manje stresa i manje razmi&scaron;ljanja. Ne razmi&scaron;ljam o povratku u javni život, ne bih snimao ni&scaron;ta novo, ovako mi je sasvim dobro. Tek sam napunio 30 godina pa se možda i predomislim. Čujem se sa kolegama iz &ldquo;Operacije Trijumf&rdquo;. Skoro me je Vuka&scaron;in zvao na neku zamenu. Sa Anom Bebić se takođe čujem, mada se ona udala i dobila dete, pa se sve manje i manje viđamo. Sada imamo različite navike i različite obaveze - rekao je nekada popularni Sajko.</p>\r\n<p>Iako je bio miljenikposebno ženskog dela publike, Nikola nije nastavio da plovi muzičkim vodama. Upravo tokom takmičenja planula je ljubav između njega i koreografkinje Milice Cerović koja je sa takmičarima svakodnevno radila na plesnim pokretima.</p>\r\n<p>Ljubav su u početku krili, a kasnije su je i obelodanili, međutim, mnogi su sumnjali u to da će njihova ljubav opstati, budući da je Milica od njega starija 10 godina.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 456px; height: 679px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2017/12/08/15/1347155_daragana-udovicic01-dragana-udovicic_ff.jpg?ver=1707736173\" alt=\"Nikola Sarić Sajko\">\r\n<figcaption>FOTO: DRAGANA UDOVIČIĆ</figcaption>\r\n</figure>\r\n<p>Ipak, Nikola i Milica pokazali su da prava ljubav ne zna za granice, pa su deset godina nakon takmičenja odlučili da se zavetuju jedno drugom na večnu ljubav.</p>\r\n<p>O ljubavi s Milicom je svojevremeno izjavio da je nakon venčanja \"sve isto samo &scaron;to sad imaju burme na rukama i jedan papir u fioci\".</p>\r\n<p>U&scaron;ao u \"Farmu\" da bi zaradio za album</p>\r\n<p>Nikola Paunović, Sajkov blizak prijatelj koji je sa njim bio u grupi OT bend, istakao je svojevremeno da je pevač veoma snalažljiv i da s njim nikada nije dosadno.</p>\r\n<p>- Znao sam da će Sajko ući na Farmu i veoma sam srećan zbog toga jer znam da s njim tamo sigurno neće biti dosadno. On će se dobro snaći jer generalno voli da ide u selo. Jo&scaron; kao dete je često posećivao dedu na selu. Seoski poslovi mu nisu strani, voli seosku idilu i sve ume da radi, sve te mu&scaron;ke poslove opravke, popravke, cepanje drva&hellip; Jedino mu je možda strano muženje krava. Ba&scaron; me zanima kako će se snaći u tome. Dobar je i kuvar i ako mu žene budu pružile priliku, sigurno će ih odu&scaron;eviti kulinarskim sposobnostima - rekao je za Nikola Paunović.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 440px; height: 297px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2018/06/28/17/1537413_sajko-1_ff.jpg?ver=1707736186\" alt=\"Nikola Sarić Sajko, Milica Cerović\">\r\n<figcaption>FOTO: DAMIR DERVI&Scaron;AGIĆ</figcaption>\r\n</figure>\r\n<p>Sajko je po izlasku iz &bdquo;Operacije trijumf&ldquo;, bio u OT bendu, a onda se odvojio i nedavno je radio muziku za seriju &bdquo;Priđi bliže&ldquo; koja se emitovala na nacionalnoj televiziji.</p>\r\n<p>- Motivi za ulazak su prvo pare, nedavno je snimio album i planira da ga uskoro izda. Ovo je dobar vid promocije. Ako pobedi, sigurno će kupiti stan - otkrio je Nikola tokom Sajkovog učestvovanja u Farmi.</p>', 5, 'odobrena', '2024-02-08 03:45:10', 31, 0, 0, 37, 'images/nikola.jpg'),
(152, 'NIKOLINA PIŠEK POKAZALA LICE BEZ TRUNKE ŠMINKE: Ovo je poruka svim HEJTERIMA... Pa usledila TRANSFORMACIJA', '<p><a href=\"https://www.kurir.rs/tag/910/nikolina-pisek\" data-taglink=\"Nikolina Pi&scaron;ek\">Nikolina Pi&scaron;ek</a>, koja uvek vodi računa da u svakom izgledu, ali voditeljka se ne libi da pokaže&nbsp;<a href=\"https://www.kurir.rs/stars/612501/nikolina-pisek-bez-sminke\" target=\"_blank\" rel=\"noopener\">kako izgleda bez trunke &scaron;minke</a>. Na svojoj dru&scaron;tvenoj mreži pokazala je kako izgleda kad nije doterana pozirajući s naočalama i neurednom pundžom te poslala poruku \"hejterima\".</p>\r\n<p>\"Ovo je poruka svim hejterima. Ako ti se ne sviđa &scaron;to radim, ali prati&scaron; sve &scaron;to radim, i dalje si moj fan\", poručila je Pi&scaron;ek.</p>\r\n<div>&nbsp;</div>\r\n<div><iframe id=\"instagram-embed-0\" style=\"width: 455px; height: 1688px; display: table; margin-left: auto; margin-right: auto;\" src=\"https://www.instagram.com/reel/C3KkvZUKWzR/embed/captioned/?cr=1&amp;v=14&amp;wp=675&amp;rd=https%3A%2F%2Fwww.kurir.rs&amp;rp=%2Fstars%2F4353273%2Fnikolina-pisek-pokazala-lice-bez-trunke-sminke-i-rascupana#%7B%22ci%22%3A0%2C%22os%22%3A180.79999999701977%2C%22ls%22%3A60.3999999910593%2C%22le%22%3A90.09999999403954%7D\" width=\"455\" height=\"1688\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\" data-instgrm-payload-id=\"instagram-media-payload-0\"></iframe></div>\r\n<p>Potom se obukla izazovnu haljinu sa full makapom i sređenom frizurom, kakvu je inače gledamo u javnosti. Fanovi su odu&scaron;evljeni njenom iskreno&scaron;ću. \"Praznik si za oči &scaron;to god da radi&scaron;\", pisali su joj u komentarima.</p>', 5, 'odobrena', '2024-02-12 03:45:08', 31, 0, 0, 37, 'images/nikolina.jpg'),
(153, 'PRISTAĆU DA JOJ DAM BILO ŠTA AKO POLUDIM!', '<p>Otac pokojnog istoričara umetnosti na krajnje vulgaran način prokomentarisao je izjavu&nbsp;<a href=\"https://www.kurir.rs/stars/4307810/nikolina-otkrila-da-joj-je-jk-nasla-advokate-u-borbi-s-misom-grofom\" target=\"_blank\" rel=\"noopener\">Nikoline Pi&scaron;ek da joj je u sporu sa svekrom i pronalasku najboljih advokata mnogo pomogla muzička zvezda Jelena Karleu&scaron;a</a>!</p>\r\n<p>Nikolina Pi&scaron;ek progovorila je o odnosu i sudskom sporu koji već godinama vodi sa ocem pokojnog supruga Vidoja, Vitorom Ristovićem.</p>\r\n<div>&nbsp;</div>\r\n<figure style=\"text-align: center;\"><img style=\"width: 446px; height: 298px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2022/06/24/14/3073867_nikolina-grof_ff.jpg?ver=1701801446\" alt=\"Mi&scaron;a Grof, Nikolina Pi&scaron;ek\">\r\n<figcaption>FOTO: NENAD KOSTIĆ, DAMIR DERVI&Scaron;AGIĆ</figcaption>\r\n</figure>\r\n<p>Kako je istakla, Mi&scaron;a Grof neprestano svojim pona&scaron;anjem \"uzurpira njen život skandaloznim optužbama i malicioznim tendencijama\".</p>\r\n<p>- Dosta ljudi me je podržalo, to je bio lep osećaj. Bila sam izbezumljena u tom periodu pa nisam ni obraćala pažnju, ali mnogo poruka podr&scaron;ke je stizalo. Svima sam im zahvalna. Jelena Karleu&scaron;a mi je mnogo pomogla, dala mi je kontakte dobrih advokata i drugih, koji su mi bili ba&scaron; korisni. Pored nje i Ana Nikolić, koja se potrudila da mi priđe i da stupi u kontakt sa mnom. Bila je preslatka.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 438px; height: 994px;\" src=\"https://www.kurir.rs/data/images/2023/11/28/19/3721016_jkk2_ff.jpg?ver=1701801461\" alt=\"Jelena Karleu&scaron;a\">\r\n<figcaption>FOTO: PRINTSCREEN/INSTAGRAM/KARLEUSASTAR</figcaption>\r\n</figure>\r\n<p>Kada je ovo pročitao Mi&scaron;a Grof, odmah je odreagovao.</p>\r\n<p>- Ko je pomogao Nikolini? Karleu&scaron;a? Ne znam ni&scaron;ta o tome. Suđenje je bilo pre mesec dana. Advokati su bili i moja biv&scaron;a snaja se bavi time. Znate, sa Nikolinom nemam nikakav kontakt. Juče sam zvao da čestitam unuci rođendan i nije se javila. Ona meni ne da da čujem Unu Sofiju. Poku&scaron;avao sam - priča on i naziva na&scaron;u pevačicu pogrdnim imenima.</p>\r\n<p>-&nbsp;<strong>Pi&scaron;ekova želi sve od moje imovine</strong>. Ne Vidojevo, nego moje! Imovinu koju sam nasledio od mog oca, majke, babe, dede, a pristaću da joj dam bilo &scaron;ta ako poludim! Znate, i vila koju ona ne da sagrađena je od mojih para! Lepo i &scaron;to je najavila da će poslati pozivnicu na useljenje, biće mi zadovoljstvo da dođem i vidim unuku - zaključuje Mi&scaron;a Grof.</p>', 5, 'odobrena', '2024-02-12 03:45:08', 31, 0, 0, 37, 'images/misa.jpg'),
(154, 'Tusk: Nema alternative partnerstvu između Evrope, NATO i SAD', '<p><strong>PARIZ</strong>&nbsp;&ndash; Ne postoji alternativa partnerstvu između Evrope, NATO i SAD za suočavanje sa sve većim bezbednosnim rizicima, izjavio je danas u Parizu poljski premijer Donald Tusk.</p>\r\n<div><ins data-ad-status=\"unfilled\" data-adsbygoogle-status=\"done\" data-ad-client=\"ca-pub-5874950475624809\" data-ad-format=\"auto\">\r\n<div id=\"aswift_3_host\" tabindex=\"0\" title=\"Advertisement\" aria-label=\"Advertisement\"><iframe id=\"aswift_3\" style=\"width: 456px; height: 191px; display: table; margin-left: auto; margin-right: auto;\" src=\"https://googleads.g.doubleclick.net/pagead/ads?client=ca-pub-5874950475624809&amp;output=html&amp;h=280&amp;adk=3131297985&amp;adf=2636307691&amp;w=668&amp;fwrn=4&amp;fwrnh=100&amp;lmt=1707753112&amp;num_ads=1&amp;rafmt=1&amp;armr=3&amp;sem=mc&amp;pwprc=3459178297&amp;ad_type=text_image&amp;format=668x280&amp;url=https%3A%2F%2Fwww.politika.rs%2Fsr%2Fclanak%2F598907%2FTusk-Nema-alternative-partnerstvu-izmedu-Evrope-NATO-i-SAD&amp;fwr=0&amp;pra=3&amp;rh=167&amp;rw=667&amp;rpe=1&amp;resp_fmts=3&amp;wgl=1&amp;fa=27&amp;uach=WyJXaW5kb3dzIiwiMTAuMC4wIiwieDg2IiwiIiwiMTIxLjAuNjE2Ny4xNDAiLG51bGwsMCxudWxsLCI2NCIsW1siTm90IEEoQnJhbmQiLCI5OS4wLjAuMCJdLFsiR29vZ2xlIENocm9tZSIsIjEyMS4wLjYxNjcuMTQwIl0sWyJDaHJvbWl1bSIsIjEyMS4wLjYxNjcuMTQwIl1dLDBd&amp;dt=1707753112782&amp;bpp=1&amp;bdt=1500&amp;idt=-M&amp;shv=r20240207&amp;mjsv=m202401310101&amp;ptt=9&amp;saldr=aa&amp;abxe=1&amp;cookie=ID%3D7ef3812db3710a9a%3AT%3D1706609678%3ART%3D1707753080%3AS%3DALNI_MYB7yus35lMHD-qSyUOSHL92xs8Rg&amp;gpic=UID%3D00000d4c96fea945%3AT%3D1706609678%3ART%3D1707753080%3AS%3DALNI_MbH5ggy6UJoV5XJcz2Ras4vYiJ3Mg&amp;eo_id_str=ID%3Dfeef7f38bc125c2b%3AT%3D1707460601%3ART%3D1707753080%3AS%3DAA-AfjZKpqigBcwMkAF-qDu_FI6j&amp;prev_fmts=1005x124%2C1200x280%2C0x0&amp;nras=4&amp;correlator=51971543284&amp;frm=20&amp;pv=1&amp;ga_vid=1024996911.1706609677&amp;ga_sid=1707753112&amp;ga_hid=502368156&amp;ga_fc=1&amp;ga_cid=1548492252.1707730600&amp;u_tz=60&amp;u_his=7&amp;u_h=864&amp;u_w=1536&amp;u_ah=824&amp;u_aw=1536&amp;u_cd=24&amp;u_sd=1.25&amp;dmc=8&amp;adx=367&amp;ady=1130&amp;biw=1519&amp;bih=703&amp;scr_x=0&amp;scr_y=100&amp;eid=44759875%2C44759926%2C44808398%2C31080793%2C31080795%2C31081025%2C44809530%2C95322748%2C95324581%2C31080872%2C95320377%2C95320868%2C95324155%2C95324161%2C95324266&amp;oid=2&amp;psts=AOrYGsl66n0aGlD_H-ncPVsbxevmt7eerIdcEn9GICJOY3PF7E0W2j63IiVArHPDTnoDjB8pAnGrm-C3ArVKj90d-MdIODPnwQ0q8XbCFbvurqwtrehw8g&amp;pvsid=4270194258562631&amp;tmod=224090366&amp;uas=0&amp;nvt=1&amp;ref=https%3A%2F%2Fwww.politika.rs%2Fsr%2Fsvet&amp;fc=384&amp;brdim=0%2C0%2C0%2C0%2C1536%2C0%2C1536%2C824%2C1536%2C703&amp;vis=1&amp;rsz=%7C%7Cs%7C&amp;abl=NS&amp;fu=128&amp;bc=31&amp;bz=1&amp;psd=W251bGwsbnVsbCxudWxsLDNd&amp;nt=1&amp;ifi=4&amp;uci=a!4&amp;btvi=2&amp;fsb=1&amp;dtd=47\" name=\"aswift_3\" width=\"456\" height=\"191\" frameborder=\"0\" marginwidth=\"0\" marginheight=\"0\" scrolling=\"no\" sandbox=\"allow-forms allow-popups allow-popups-to-escape-sandbox allow-same-origin allow-scripts allow-top-navigation-by-user-activation\" allow=\"attribution-reporting\" data-load-complete=\"true\" data-google-container-id=\"a!4\"></iframe></div>\r\n</ins></div>\r\n<p>Tusk je stigao u Pariz u okviru mini turneje tokom koje će posetiti i Berlin, u nastojanju da uspostavi bliže veze sa dve najveće evropske sile, jer rat u Ukrajini ulazi u treću godinu, a evropske prestonice razmatraju mogućnost da se biv&scaron;i predsednik SAD Donald Tramp vrati u Belu kuću, preneo je Rojters.</p>\r\n<p><a href=\"https://www.politika.rs/sr/clanak/598923/Zaharova-Optuzivanje-Rusije-za-mesanje-u-demokratske-procese-EU-apsurd)\"><img style=\"width: 296px; height: 168px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_677z381_677z381_677z381_2624297_image3_ls.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.politika.rs/sr/clanak/598923/Zaharova-Optuzivanje-Rusije-za-mesanje-u-demokratske-procese-EU-apsurd)\">Zaharova: Optuživanje Rusije za me&scaron;anje u demokratske procese EU&hellip;</a></span></h3>\r\n<p>&nbsp;</p>\r\n<p>Tramp je tokom vikenda izazvao negodovanje među zapadnim partnerima nakon &scaron;to je nagovestio da SAD možda neće za&scaron;tititi NATO saveznike koji ne tro&scaron;e dovoljno na odbranu od potencijalnog ruskog napada.</p>\r\n<p>&bdquo;Nema alternative EU, NATO, transatlantskoj saradnji&rdquo;, istakao je Tusk, javlja Tanjug.</p>\r\n<p>Poljski premijer, koji se pridružio predsedniku Francuske Emanuelu Makronu na radnom ručku u Jelisejskoj palati, rekao je da njegova poseta ima cilj da &bdquo;revitalizuje odnose Poljske sa najvažnijim evropskim partnerima&rdquo;, preneo je AP.</p>\r\n<p><a href=\"https://www.politika.rs/sr/clanak/598922/Solc-Nemacka-ce-izdvojiti-dva-odsto-BDP-za-NATO)\"><img style=\"width: 311px; height: 176px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_solc-nato.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.politika.rs/sr/clanak/598922/Solc-Nemacka-ce-izdvojiti-dva-odsto-BDP-za-NATO)\">&Scaron;olc: Nemačka će izdvojiti dva odsto BDP za NATO</a></span></h3>\r\n<p>&nbsp;</p>\r\n<p>&bdquo;Evropa mora da postane siguran kontinent, a to znači da EU, Francuska i Poljska moraju da postanu zemlje koje su jake i spremne da brane svoje granice, svoju teritoriju i da brane i podržavaju svoje saveznike i prijatelje izvan Evropske unije&rdquo;, istakao je Tusk.</p>\r\n<div><ins data-ad-status=\"filled\" data-adsbygoogle-status=\"done\" data-ad-client=\"ca-pub-5874950475624809\" data-ad-format=\"auto\">\r\n<div id=\"aswift_4_host\" tabindex=\"0\" title=\"Advertisement\" aria-label=\"Advertisement\"><iframe id=\"aswift_4\" style=\"width: 439px; height: 184px;\" src=\"https://googleads.g.doubleclick.net/pagead/ads?client=ca-pub-5874950475624809&amp;output=html&amp;h=280&amp;adk=3131297985&amp;adf=1919609010&amp;w=668&amp;fwrn=4&amp;fwrnh=100&amp;lmt=1707753112&amp;num_ads=1&amp;rafmt=1&amp;armr=3&amp;sem=mc&amp;pwprc=3459178297&amp;ad_type=text_image&amp;format=668x280&amp;url=https%3A%2F%2Fwww.politika.rs%2Fsr%2Fclanak%2F598907%2FTusk-Nema-alternative-partnerstvu-izmedu-Evrope-NATO-i-SAD&amp;fwr=0&amp;pra=3&amp;rh=167&amp;rw=667&amp;rpe=1&amp;resp_fmts=3&amp;wgl=1&amp;fa=27&amp;uach=WyJXaW5kb3dzIiwiMTAuMC4wIiwieDg2IiwiIiwiMTIxLjAuNjE2Ny4xNDAiLG51bGwsMCxudWxsLCI2NCIsW1siTm90IEEoQnJhbmQiLCI5OS4wLjAuMCJdLFsiR29vZ2xlIENocm9tZSIsIjEyMS4wLjYxNjcuMTQwIl0sWyJDaHJvbWl1bSIsIjEyMS4wLjYxNjcuMTQwIl1dLDBd&amp;dt=1707753112782&amp;bpp=1&amp;bdt=1500&amp;idt=-M&amp;shv=r20240207&amp;mjsv=m202401310101&amp;ptt=9&amp;saldr=aa&amp;abxe=1&amp;cookie=ID%3D7ef3812db3710a9a%3AT%3D1706609678%3ART%3D1707753080%3AS%3DALNI_MYB7yus35lMHD-qSyUOSHL92xs8Rg&amp;gpic=UID%3D00000d4c96fea945%3AT%3D1706609678%3ART%3D1707753080%3AS%3DALNI_MbH5ggy6UJoV5XJcz2Ras4vYiJ3Mg&amp;eo_id_str=ID%3Dfeef7f38bc125c2b%3AT%3D1707460601%3ART%3D1707753080%3AS%3DAA-AfjZKpqigBcwMkAF-qDu_FI6j&amp;prev_fmts=1005x124%2C1200x280%2C0x0%2C668x280&amp;nras=5&amp;correlator=51971543284&amp;frm=20&amp;pv=1&amp;ga_vid=1024996911.1706609677&amp;ga_sid=1707753112&amp;ga_hid=502368156&amp;ga_fc=1&amp;ga_cid=1548492252.1707730600&amp;u_tz=60&amp;u_his=7&amp;u_h=864&amp;u_w=1536&amp;u_ah=824&amp;u_aw=1536&amp;u_cd=24&amp;u_sd=1.25&amp;dmc=8&amp;adx=367&amp;ady=2140&amp;biw=1519&amp;bih=703&amp;scr_x=0&amp;scr_y=100&amp;eid=44759875%2C44759926%2C44808398%2C31080793%2C31080795%2C31081025%2C44809530%2C95322748%2C95324581%2C31080872%2C95320377%2C95320868%2C95324155%2C95324161%2C95324266&amp;oid=2&amp;psts=AOrYGsl66n0aGlD_H-ncPVsbxevmt7eerIdcEn9GICJOY3PF7E0W2j63IiVArHPDTnoDjB8pAnGrm-C3ArVKj90d-MdIODPnwQ0q8XbCFbvurqwtrehw8g&amp;pvsid=4270194258562631&amp;tmod=224090366&amp;uas=0&amp;nvt=1&amp;ref=https%3A%2F%2Fwww.politika.rs%2Fsr%2Fsvet&amp;fc=384&amp;brdim=0%2C0%2C0%2C0%2C1536%2C0%2C1536%2C824%2C1536%2C703&amp;vis=1&amp;rsz=%7C%7Cs%7C&amp;abl=NS&amp;fu=128&amp;bc=31&amp;bz=1&amp;psd=W251bGwsbnVsbCxudWxsLDNd&amp;nt=1&amp;ifi=5&amp;uci=a!5&amp;btvi=3&amp;fsb=1&amp;dtd=56\" name=\"aswift_4\" width=\"439\" height=\"184\" frameborder=\"0\" marginwidth=\"0\" marginheight=\"0\" scrolling=\"no\" sandbox=\"allow-forms allow-popups allow-popups-to-escape-sandbox allow-same-origin allow-scripts allow-top-navigation-by-user-activation\" allow=\"attribution-reporting\" data-load-complete=\"true\" data-google-query-id=\"CL7N6IyUpoQDFTQyrQYdlEYCjg\" data-google-container-id=\"a!5\"></iframe></div>\r\n</ins></div>\r\n<p>&bdquo;Verovatno ovde u Parizu reči iz \'Tri musketara\' Aleksandra Dime najjasnije odjekuju: Svi za jednog i jedan za sve&rdquo;, rekao je on.</p>\r\n<p>Makron je pohvalio &bdquo;ključnu ulogu&rdquo; Francuske i Poljske u bezbednosti i odbrani u Evropi u kontekstu rata u Ukrajini.</p>\r\n<p>Volja Evrope za dalje snabdevanje i zadovoljavanje ukrajinskih potreba je ključna, rekao je on.</p>\r\n<p>&bdquo;To će nam omogućiti da od Evrope napravimo bezbednosnu i odbrambenu silu koja je istovremeno komplementarna NATO-u i stub Atlantske alijanse&rdquo;, rekao je Makron</p>\r\n<p>.<a href=\"https://www.politika.rs/sr/clanak/598920/Papa-primio-Havijera-Mileja-sastanak-iza-zatvorenih-vrata-trajao-oko-sat-vremena)\"><img style=\"width: 387px; height: 219px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_12019573.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.politika.rs/sr/clanak/598920/Papa-primio-Havijera-Mileja-sastanak-iza-zatvorenih-vrata-trajao-oko-sat-vremena)\">Papa primio Havijera Mileja, sastanak iza zatvorenih vrata trajao&hellip;</a></span></h3>\r\n<p>Var&scaron;ava, Pariz i Berlin vide jedinstvo EU u odbrani i jačanje podr&scaron;ke 27 država članica Ukrajini ključnim u trenutku kada se podr&scaron;ka SAD Kijevu koleba usred političkih sukoba u Va&scaron;ingtonu.</p>', 6, 'odobrena', '2024-01-17 04:02:09', 32, 0, 0, 38, 'images/nato.jpg'),
(155, 'Nariškin: Zapad razmatra šefa NATO-a za ulogu proksi vladara u Ukrajini', '<p><strong>MOSKVA</strong>&nbsp;&ndash; Direktor ruske Spoljne obave&scaron;tajne službe (SVR) Sergej Nari&scaron;kin izjavio je danas da Zapad razmatra da postavi generalnog sekretara NATO-a Jensa Stoltenberga i druge &bdquo;rusofobične američke i evropske političare&rdquo; za ulogu proksi vladara u Ukrajini.</p>\r\n<p>&bdquo;&Scaron;irok spektar rusofobično nastrojenih američkih i evropskih političara pretenduje na ulogu takvog de fakto proksi vladara u ime Zapada u Ukrajini. Među njima se ističe generalni sekretar NATO-a Jens Stoltenberg, koji odmah po zavr&scaron;etku sada&scaron;njeg mandata u Briselu želi da ide u Kijev da nadgleda red&rdquo;, rekao je &scaron;ef obave&scaron;tajne službe, prenosi TASS.</p>\r\n<p><a href=\"https://www.politika.rs/sr/clanak/598923/Zaharova-Optuzivanje-Rusije-za-mesanje-u-demokratske-procese-EU-apsurd)\"><img style=\"width: 304px; height: 172px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.politika.rs/thumbs//upload/Article/Image/2024_02///294z166_677z381_677z381_677z381_2624297_image3_ls.jpg\" width=\"258\" height=\"146\"></a></p>\r\n<h3 style=\"text-align: center;\"><span style=\"font-size: 12pt;\"><a href=\"https://www.politika.rs/sr/clanak/598923/Zaharova-Optuzivanje-Rusije-za-mesanje-u-demokratske-procese-EU-apsurd)\">Zaharova: Optuživanje Rusije za me&scaron;anje u demokratske procese EU&hellip;</a></span></h3>\r\n<p>&nbsp;</p>\r\n<p>Nari&scaron;kin je dodao da se o ovom pitanju razgovara jer su &bdquo;mnogi Ukrajinci počeli da shvataju da je &bdquo;ostvarenje ciljeva specijalne vojne operacije Rusije neizbežno&rdquo;, javlja Tanjug.</p>', 6, 'odobrena', '2024-02-12 04:02:08', 32, 0, 0, 38, 'images/ukrajina.jpg'),
(156, 'DA LI EVROPI PRETI APOKALIPSA?! Naučnici otkrili ŠTA nas očekuje na globalnom nivou, pa sve uporedili sa scenariom POZNATOG FILMA', '<p><strong>U filmu \"Dan posle sutra\" iz 2004., čovečanstvo je uronjeno u jezivu svetsku oluju koja &scaron;alje planetu u novo&nbsp;<a href=\"https://www.kurir.rs/tag/21887/ledeno-doba\" target=\"_blank\" rel=\"noopener\">ledeno doba</a>.</strong></p>\r\n<p>I iako je ovo scenario blokbastera iz oblasti naučne fantastike, naučno obja&scaron;njenje koje stoji iza svega ovoga je istinito.</p>\r\n<div>&nbsp;</div>\r\n<p>Za nekoliko decenija, topljenje glečera moglo bi da blokira Golfsku struju (sistem struja koji donosi toplotu severnoj hemisferi), kažu stručnjaci.</p>\r\n<p><strong>Autori studije, sa Univerziteta u Utrehtu u Holandiji, ne znaju tačno kada će se kolaps desiti, iako je prethodna studija to pokazala već sledeće godine.</strong></p>\r\n<p>\"Približavamo se kolapsu, ali nismo sigurni koliko smo blizu\", rekao je glavni autor Rene van Vesten, klimatski naučnik i okeanograf sa Univerziteta u Utrehtu.</p>\r\n<p><strong>\"Idemo ka prelomnoj tački.\"</strong></p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 501px; height: 333px;\" src=\"https://www.kurir.rs/data/images/2021/08/05/21/2670089_grenland-led-i-golfska-struja_ff.jpg?ver=1707741244\" alt=\"0609771335, Golfska struja, Grenland, led, ledene ploče, globalno zagrevanje\">\r\n<figcaption>FOTO: ULRIK PEDERSEN/NURPHOTO / SHUTTERSTOCK EDITORIAL / PROFIMEDIA</figcaption>\r\n</figure>\r\n<p>Kada bi se globalna vremenska nepogoda poput one u gore pomenutom filmu mogla dogoditi je pitanje od milion dolara, prema van Vestenu.</p>\r\n<p><strong>\"Nažalost, trenutno ne možemo da odgovorimo na to\"</strong>, rekao je on.</p>\r\n<p>\"To takođe zavisi od stope klimatskih promena koje izazivamo kao čovečanstvo.\"</p>\r\n<p>Golfska struja je deo mnogo &scaron;ireg sistema struja, zvanično nazvanog Atlantic Meridional Overturning Circulation ili AMOC.</p>\r\n<p>Opisana kao \'transportna traka okeana\', ona prenosi toplu vodu blizu povr&scaron;ine okeana ka severu &ndash; od tropskih krajeva do severne hemisfere.</p>\r\n<p>Kada topla voda stigne do severnog Atlantika (oko Evrope i Velike Britanije, i istočne obale SAD), ona oslobađa toplotu i smrzava se.</p>\r\n<p>Kako se ovaj led formira, so ostaje u okeanskoj vodi.</p>', 6, 'odobrena', '2024-02-12 04:02:09', 32, 0, 0, 38, 'images/apokalipsa.jpg'),
(157, 'LETNJA TEMPERATURA USRED JANUARA: Toplotni talas sa severa Afrike penje živu na termometru i do 28 podeoka u ovim delovima Evrope', '<p>Jugozapadni i zapadni deo Evrope usred zime zahvatila je veoma topla vazdu&scaron;na masa sa severa Afrike. Iznad jugozapada Evrope i severozapada Afrike nalazi se veoma snažan i izražen anticiklon, uz formiranje veoma tople vazdu&scaron;ne mase.</p>\r\n<p>&Scaron;irom &Scaron;panije i Portugalije danas preovladavaju prave prolećne tempeature uz vrednosti i iznad 20&deg;C, u Portugaliji do 23&deg;C, a najtoplije je na jugoistoku i istoku &Scaron;panije, uz temperature i do letnjih 25-26&deg;C. Istovremeno je sunčano, odnosno nebo je potpuno vedro i bez oblaka.</p>\r\n<div>&nbsp;</div>\r\n<p>Veoma topla vazdu&scaron;na masa stigla je i do zapada Evrope, pa tako temperatura na jugu Franuske dostiže 20&deg;C,a &scaron;irom zemlje prelazi 15&deg;C. Topao vazduh zahvatio je i Italiju. Istovremeno, topla vazdu&scaron;na masa &scaron;iri se prema centralnim i severnim predelima Evrope, pa se tako u centralnoj Evropi beleži i do 15&deg;C, na jugu Skandinavije do 10&deg;C.</p>\r\n<p>Ova topla vazdu&scaron;na masa potisnula je veoma hladnu sa istoka Evrope dalje ka Sibiru, a ledeno je ostalo samo u Laponiji, odnosno na severoistoku Skandinavije, uz temperature i tokom dana oko -25&deg;C.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 468px; height: 473px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/01/24/19/3802116_vr_ff.jpg?ver=1706122481\" alt=\"vreme\">\r\n<figcaption>FOTO: PRINTSCREEN PLAY.GOOGLE.COM</figcaption>\r\n</figure>\r\n<p>Jo&scaron; toplije na jugozapadu Evrope biće u četvrtak, uz temperature &scaron;irom zapadne i jugozapadne Evrope, zapadnog Mediterana i Italije i iznad 20&deg;C. Najtoplije biće u &Scaron;paniji i Portugaliji, uz temperature uglavnom iznad 18&deg;C, a u mnogim predelima iznad 20&deg;C. Najtoplije će biti na istoku i jugoistoku &Scaron;panije, uz temperature i iznad letnjih 25&deg;C, lokalno i do 28&deg;C. Najtoplije će biti na &scaron;irem području Valensije i Mursije.</p>\r\n<p>Aktuelne i očekivane temperature vi&scaron;e su za 10 ak stepeni od prosečnih za ovo doba godine. Inače, za &scaron;ire područje Valensije i Mursije najvi&scaron;a temperatura izmerena u januaru je 27-28&deg;C, tako da postoji mogućnost da sutra u pojedinim predelima budu oboreni rekordi za januar mesec otkad se vr&scaron;e merenja.</p>\r\n<p>Ovih dana nije veoma toplo samo na obali Mediterana, već i preko kontinentalnih predela sve do Atlantika. Pravo proleće beleži se i u Madridu, uz temperature oko 20&deg;C. Pod uticajem napomenutog anticklona veoma toplo vreme na jugozapadu Evrope biće sve do petka, a termički visinski greben prostiraće se sve do Alpa i centralnog Mediterana, ali i preko zapadne Evrope delom do centralne.</p>\r\n<p>Postepeni pad temperature vazduha u &Scaron;paniji i Portugaliji očekuje se od vikenda i vrednosti bi se vratile na prosečne uz obalna područja Mediterana, a to su vrednosti od 15 do 20&deg;C, unutar kopna na oko 10&deg;C.Južni i jugoistočni deo &Scaron;panije, jug Portugalije, jug Sicilije, krajnji jug Grčke, Malta i južna obakla Kipra tokom zimskih meseci imaju najvi&scaron;e tempertature u Evropi, u proseku tokom januara od 15 do 20&deg;C, a neretko pređu i 20&deg;C.</p>', 6, 'odobrena', '2024-02-12 04:02:08', 32, 0, 0, 38, 'images/tmperatura.jpg'),
(158, 'Srbija spremna da kupi deo luka Solun i Pireji! Predsednik Vučić: Potrebni su nam ti kapaciteti zbog rasta izvoza', '<p>- Važno nam je da koristimo kapacitete Soluna i Pireja, da kupimo deo&nbsp;<a id=\"5e12f6e3-86dd-453b-80f0-5d43de508bde\" href=\"https://www.blic.rs/luka\">luke</a>. Kada povećamo automobilsku proizvodnju, sa rudnicima, železarom, to će nam biti potrebno, izjavio je predsednik Srbije Aleksandar Vučić. </p>\r\n<figure>\r\n<div style=\"text-align: center;\">\r\n<figure><picture><img style=\"width: 419px; height: 279px;\" src=\"https://ocdn.eu/pulscms-transforms/1/bO3k9kpTURBXy85NzNiMGIzYzlhNWZkZmJlNTZjZDE3MTQzNmUyZDRjOS5qcGeRkwLNBLAA3gABoTAB\" alt=\".\" width=\"1200\" height=\"800\" data-original-image=\"//ocdn.eu/pulscms-transforms/1/bO3k9kpTURBXy85NzNiMGIzYzlhNWZkZmJlNTZjZDE3MTQzNmUyZDRjOS5qcGeRkwLNBLAA3gABoTAB\" data-src=\"//ocdn.eu/pulscms-transforms/1/bO3k9kpTURBXy85NzNiMGIzYzlhNWZkZmJlNTZjZDE3MTQzNmUyZDRjOS5qcGeRkwLNBLAA3gABoTAB\"></picture></figure>\r\nFOTO: VLADIMIR &Scaron;PORČIĆ / TANJUG</div>\r\n<figcaption>.</figcaption>\r\n</figure>\r\n<p>Kako je istakao predsednik grčke kompanije i finansijske insitutcije su dobrodo&scaron;le u Srbiji, i dodao da dve zemlje zajednički mogu mnogo toga da urade.</p>\r\n<p>- Moraćemo da radimo vi&scaron;e i da se borimo za svaku i grčku i srpsku kompaniju, da se borimo i za na&scaron; ulazak na grčko trži&scaron;te u različitim oblastima, ali da privlačimo &scaron;to je moguće vi&scaron;e grčkih kompanija ovde, rekao je predsednik.</p>', 1, 'na čekanju', '2024-02-12 17:22:51', 27, 0, 0, NULL, 'images/solun.jpg'),
(159, 'MEDVEDEV NAJAVIO ZASTRAŠUJUĆI SCENARIO: Biće još gore, Ukrajinci će bombardovati svoje gradove i sela!', '<p>Priča o uni&scaron;tenju aviona Il-76 je priča o unutra&scaron;njoj političkoj borbi neonacističkih elita u Kijevu, \"borba svinja u koritu\", napisao je danas na Telegramu zamenik predsednika Saveta bezbednosti Ruske Federacije Dmitrij Medvedev nakon vesti da se vojno-transportni avion Il-76, koji je prevozio 65 pripadnika Oružanih snaga Ukrajine na razmenu sru&scaron;io u Belgorodskoj oblasti Rusije.</p>\r\n<p>Oblast se, podsetimo, nalazi na samoj granici sa Ukrajinom, i od početka Specijalne vojne operacije redovna je meta ukrajinskih snaga.</p>\r\n<div>&nbsp;</div>\r\n<p>\"Večan pomen na&scaron;im pilotima. Oni su heroji\", prokomentarisao je Medvedev i dodao da ni \"ukrajinske porodice nisu dočekale svoje iz Rusije\".</p>\r\n<p>\"Biće jo&scaron; gore. Ovi izrodi, da bi se održali na vlasti, s lakoćom će ubijati svoja vojna lica i ratne zarobljenike, &scaron;to su naučili za 700 dana Specijalne vojne operacije. Oni će nemilosrdno bombardovati svoje gradove i sela, pretvarajući u pepeo njihove domove i spaljujući njihove starce i decu\".</p>\r\n<p>Za njih ne postoje nikakva ograničenja, jer se radi o novcu i vlasti, pojasnio je Medvedev.</p>\r\n<div>\r\n<div><iframe id=\"twitter-widget-0\" style=\"width: 493px; height: 245px;\" title=\"X Post\" src=\"https://platform.twitter.com/embed/Tweet.html?creatorScreenName=KurirVesti&amp;dnt=false&amp;embedId=twitter-widget-0&amp;%3D%3D&amp;frame=false&amp;hideCard=false&amp;hideThread=false&amp;id=1750090312037413247&amp;lang=sr&amp;maxWidth=560px&amp;origin=https%3A%2F%2Fwww.kurir.rs%2Fplaneta%2F4346116%2Fmedvedev-najavio-zastrasujuci-scenario-bice-jos-gore-ukrajinci-ce-bombardovati-svoje-gradove-i-sela&amp;sessionId=764d79714c337afd7cd58ecc3afd7f711ce7ae80&amp;siteScreenName=KurirVesti&amp;theme=light&amp;widgetsVersion=2615f7e52b7e0%3A1702314776716&amp;width=550px\" width=\"493\" height=\"245\" frameborder=\"0\" scrolling=\"no\" allowfullscreen=\"allowfullscreen\" data-tweet-id=\"1750090312037413247\"></iframe></div>\r\n</div>\r\n<p>Ruska strana nakon napada poručila je da je za obaranje aviona kriv Kijev. To je rekao predsednik Dume Vjačeslav Volodin, a potvrdilo je rusko Ministarstvo odbrane, dok su iz Kremlja za sada odlučili da se uzdrže od komentara. Jedan od poslanika Dume otkrio je da je Kijev znao putanju aviona koji je prevozio ukrajinske vojnike.</p>\r\n<p>Ukrajinski mediji, među kojima su \"RBC-Ukrajina\" i \"Ukrajinska pravda\" pi&scaron;u da su Oružane snage Ukrajine oborile Il-76.</p>\r\n<p>Ipak, ukrajinski zvaničnici za sada su samo rekli da potvrđuju da je za danas bila planirana razmena zarobljenika, ali da, kao &scaron;to su rekli iz Glavne obave&scaron;tajne uprave ukrajinske vojske, konstatuju da se \"razmena danas neće održati\".</p>', 1, 'draft', '2024-02-09 17:25:09', 27, 0, 0, NULL, 'images/medevedev.jpg'),
(160, 'SVI SU SE PITALI GDE JE JOKIĆ, ODGOVOR JE JEDNOSTAVAN! Evo zbog čega srpski as nije bio na sahrani Dejana Milojevića!', '<p><a href=\"https://www.kurir.rs/sport/kosarka/4353217/sahrana-dejana-milojevica\" target=\"_blank\" rel=\"noopener\">Dejan Milojević sahranjen je danas u Beogradu</a>&nbsp;na Novom bežanijskom groblju.</p>\r\n<p>Od njega su se mnogi oprostili, do&scaron;ao je i trener Golden Stejta Stiv Ker zajedno sa saradnicima. Među svima njima nije bilo jedno lice -&nbsp;<a href=\"https://www.kurir.rs/tag/255597/nikola-jokic\" data-taglink=\"Nikola Jokić\">Nikola Jokić</a>. Mnogi su se pitali za&scaron;to on nije do&scaron;ao.</p>\r\n<div>&nbsp;</div>\r\n<p>Odgovor je prilično jednostavan, zbog rasporeda Denvera i klupskih obaveza. Put iz Amerike do Srbije, pa povratak i sve to u momentima kada se Nagetsi bore za prvo mesto na Zapadu bio bi predug i verovatno bi mu i zbog svega toga bilo potrebno jo&scaron; vremena i za emotivni oporavak.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 458px; height: 322px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/01/18/00/3792930_dejanmilojevicoprostaj41660_ff.jpg?ver=1707750776\" alt=\"Nikola Jokić, Dejan Milojević\">\r\n<figcaption>FOTO: STARSPORT&copy;</figcaption>\r\n</figure>\r\n<p>Već u noći između ponedeljka i utorka Denver igra derbi protiv Milvokija na gostovanju. Posle toga slede dueli sa Sakramentom, koji ih je nedavno razbio sa 29 poena razlike, pa sa Va&scaron;ingtonom i Portlandom. U ponedeljak 26 februara (1 ujutru po na&scaron;em vremenu) gostovaće Golden Stejtu, timu u kom je Milojević radio.</p>\r\n<p>Srpski centar nije želeo da privlači pažnju svojim izjavama, pa je tako odlučio da ne priča previ&scaron;e o Dekiju. \"Volim ga\", rekao je Nikola na temu koja mu je veoma bolna, a zatim nastavio: \"Moja porodica je u &scaron;oku. ja volim celu njegovu familiju. Ne želim da pravim cirkus od toga\", poručio je Jokić koji je nedavno nosio majicu sa natpisom \"Brate\" u njegovu čast.</p>', 2, 'na čekanju', '2024-02-12 17:28:47', 28, 0, 0, NULL, 'images/jokic.jpg'),
(161, 'SRBIJA IMA RECEPT ZA HRVATSKU: Znamo šta je ulog, ovo je KLJUČ pobede!', '<p><strong>Vaterpolisti Srbije</strong>&nbsp;sastaju se sa Hrvatskom u četvrtfinalu Svetskog prvenstva u Dohi.</p>\r\n<p>Nema dileme da nas očekuju pravi spektakl u duelu velikih rivala.</p>\r\n<div>&nbsp;</div>\r\n<p><a href=\"https://www.kurir.rs/tag/97/srbija\" data-taglink=\"Srbija\">Srbija</a>&nbsp;ima razloga za optimizam, dosada&scaron;nje utakmice u Dohi, tri pobede u grupi uz dobre igre ukazuju da sastav Uro&scaron;a Stevanovića može mnogo.</p>\r\n<p>\"<em>Hrvatska je u odnosu na Evropsko prvenstvo u Zagrebu samo malo promenila tim. Nema povređenog Bukića tu je iskusni centar Krapić. Na golu nije vi&scaron;e kao rezerva Popadić, priliku je dobio Anić. Sve ostalo je isto. Zna se kakav je ulog u četvrtfinalu, prvi finalni susret na svakom &scaron;ampionatu</em>\", rekao je Stefan Ćirić, prvi saradnik selektora Srbije Uro&scaron;a Stevanovića.</p>\r\n<p>Upravo je Ćirić trenirao Krapića, zna odlično sve vrline hrvatske ekipe kojoj su centri bitni aduti. Vrlić, Lončar, Krapić su problem za sve bekove.</p>\r\n<p>\"<em>Nisu samo centri bitni, ne zaboravite Bijača jednog od najboljih golmana na svetu, jaka je spoljna linija, Fatović uvek opasan u kontri, tu je opasan &scaron;uter Kragić, da ne nabrajam vi&scaron;e. Ponavljam odlična ekipa. Nama je najvažnije da ispunimo na&scaron; plan, da odigramo kako znamo. Možda je opomena slabiji početak Amerike koji sada ne treba da se dogodi. Ne smemo da dobijamo golove iz kontri, da im omoguće lake pogotke. Treba da se držimo pozicione igre i tu tražimo svoju &scaron;ansu</em>\", ističe Ćirić.</p>\r\n<p>&nbsp;</p>', 2, 'draft', '2024-02-12 17:29:56', 28, 0, 0, NULL, 'images/srbija_vaterpolo.jpg'),
(162, 'NAJLEPŠI STANOVI I KUĆE POZNATIH SRPKINJA: Evo u kakvom luksuzu uživaju najpopularnije dame sa naše scene! Sve su uredile po želji', '<p><strong>Kada se svetla reflektora ugase, žene sa javne scene uživaju u mirnom ambijentu svojih&nbsp;<a href=\"https://www.kurir.rs/tag/22640/dom\" target=\"_blank\" rel=\"noopener\">domova</a>&nbsp;gde sa članovima porodice dele dragocene trenutke.</strong>&nbsp;One dosta truda ulažu u uređenje enterijera, a ovo su&nbsp;<strong>pet najlep&scaron;ih domova na&scaron;ih poznatih dama koji su zaista stvoreni za uživanje.</strong></p>\r\n<p><strong>Jelena Gavrilović</strong></p>\r\n<p>Popularna srpska glumica Jelena Gavrilović već nekoliko godina živi u luksuznom domu sa svojim verenikom Dariom, u Beogradu na vodi.</p>\r\n<p>Unutra&scaron;njost stana već na prvi pogled liči na prizore koje viđamo u magazinima, a kako uživa u svom domu Jelena je u vi&scaron;e navrata delila sa svojim pratiocima na Instagramu.</p>\r\n<div>&nbsp;</div>\r\n<p>Tako smo jednom prilikom mogli da vidimo kako se ba&scaron;kari u udobnom kauču, okružena zanimljivim detaljima poput zlatne lampe i interesantnih slika na zidu.</p>', 4, 'na čekanju', '2024-02-12 17:32:52', 30, 0, 0, NULL, 'images/poznati.jpg'),
(163, 'ŠTA POSLE RATA, O TOME MALO KO RAZMIŠLJA?\" Nikola Popević o sličnim sudbinama Miloša Bikovića, Kevina Spejsija i Novaka Đokovića', '<p>Od nastanka ova kolumna služila je uglavnom kao mesto gde sam objavljivao kritike i utiske, nisam je koristio za komentarisanje aktuelnih događaja. Izuzetak bih napravio za&nbsp;<a href=\"https://www.kurir.rs/zabava/kultura/4349973/bikovic-je-laka-meta-nikola-popevic\" target=\"_blank\" rel=\"noopener\">\"slučaj Biković\"</a>, ne samo zbog lokalnog značaja, jer je reč o na&scaron;em glumcu, već i zato &scaron;to je ujedno odjek globalnih trendova aktuelnih već poduži niz godina. U svom prvom reagovanju nisam iskazao čuđenje, naprotiv. Vi&scaron;e me je začudilo &scaron;to je HBO dao Bikoviću ulogu nego &scaron;to je reagovalo Ministarstvo spoljnih poslova Ukrajine.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 378px; height: 566px;\" src=\"https://www.kurir.rs/data/images/2021/05/22/09/2577617_nikola-popevic01-news1-zorana-jevtic_ff.jpg?ver=1707730176\" alt=\"Nikola Popević\">\r\n<figcaption>FOTO: ZORANA JEVTIĆ</figcaption>\r\n</figure>\r\n<div>&nbsp;</div>\r\n<p>Poslovno gledano, jasno je za&scaron;to je uloga ruskog gurua za zdravlje data&nbsp;<a href=\"https://www.kurir.rs/tag/48213/milos-bikovic\" target=\"_blank\" rel=\"noopener\">Bikoviću&nbsp;</a>- reč je o čoveku koji u Rusiji glumi Ruse i pritom govori na ruskom, bez nadsinhronizacije. Dokazao se u svom poslu, zanimljiv je dodatak ansamblu \"Belog lotosa\" i sve je to dokaz da su se ljudi iz HBO najpre vodili isključivo profesionalnim motivima i o politici nisu brinuli. Međutim, s druge strane, Ukrajina od početka rata vrlo otvoreno apeluje na povlačenje kompanija iz Rusije.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 437px; height: 605px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/02/04/15/3808784_bikovic05-news1-zorana-jevtic_ff.jpg?ver=1707730195\" alt=\"Milo&scaron; Biković\">\r\n<figcaption>FOTO: ZORANA JEVTIĆ</figcaption>\r\n</figure>\r\n<p>Po&scaron;to je Zapad kolektivno stao na stranu Ukrajinaca, prekinuti su tokovi velikog novca. Neke kompanije su se povukle same, ali neke koje su u tome oklevale su imenovali čelnici države, čak i gigante poput \"Renoa\", koji je imao fabriku u Rusiji i sada se u tim pogonima pokreće proizvodnja novih \"moskviča\".</p>\r\n<p>Sajt leave-russia.org služi za praćenje u kolikoj meri svetske kompanije zadržavaju poslove u Rusiji ili su se povukle. Pregledom tog sajta jasno je da neka velika zapadna imena i dalje tamo posluju, a kad se na sve to doda i činjenica da je zamrznut ogroman novac ruske države, ali i pojedinaca bliskih tamo&scaron;njim vlastima, dakle privatna imovina, jasno je da bi spram svih tih milijardi srpski glumac mogao biti laka meta za sitnu PR pobedu i pokazivanje da Ukrajina i dalje ima uticaj na velike zapadne kompanije.</p>\r\n<p>Ali &scaron;ta posle rata, o tome malo ko razmi&scaron;lja i ovo će klupko biti te&scaron;ko razmrsiti. Tzv. kultura poni&scaron;tavanja nije ne&scaron;to toliko novo, oduvek su ljudi bliski nekim starim režimima bili sprečavani da dalje rade, pa i proganjani. I u tome se nisu isticala samo autokratska dru&scaron;tva, u demokratskim poput SAD javljale su se pojave kao &scaron;to je Makartijev \"lov na crvene ve&scaron;tice\", u kom su probleme imala i velika imena američkog filma. S razvojem medija i neslućenim jačanjem kompanija koje pružaju medijske usluge, \"kultura poni&scaron;tavanja\" se razvila do tačke u kojoj smo danas.</p>', 4, 'draft', '2024-02-12 17:34:44', 30, 0, 0, NULL, 'images/zabava.jpg'),
(164, 'NOVA HAPŠENJA ZBOG PROSTITUCIJE U BEOGRADU : Ovo je bila njegova uloga u lancu, policija intenzivo traga za ostalim!', '<p>Osumnjičeni I. Z. (26) uhap&scaron;en je u nastavku&nbsp;<strong><a href=\"https://www.kurir.rs/tag/1045476/uros-panic\" target=\"_blank\" rel=\"noopener\">akcije hap&scaron;enja učesnika u lancu prostitucije</a></strong>&nbsp;koja je sprovedena od strane Trećeg osnovnog javnog tužila&scaron;tva u Beogradu i policijskih službenika PU za grad Beograd.</p>\r\n<p>Osumnjičenom se stavlja na teret da je zajedno sa osumnjičenima V.S. i S.L., koji su uhap&scaron;eni pre nekoliko dana i sa osumnjičenima U.P. i M.P., za kojima se intenzivno traga, preduzeo radnje navođenja, podsticanja i organizovanja predaje o&scaron;tećenih ženskih lica drugim licima radi prostitucije.</p>\r\n<p>Osumnjičenom je određeno zadržavanje do 48 časova, a dana 14.02.2024. godine će biti saslu&scaron;an u Trećem osnovnom javnom tužila&scaron;tvu u Beogradu.</p>\r\n<p>Treće osnovno javno tužila&scaron;tvo u Beogradu nastavlja da, u saradnji sa Ministarstvom unutra&scaron;njih poslova, radi na otkrivanju svih učenika predmetnog događaja, rasvetljavanju svih činjenica i razbijanju lanca prostitucije.</p>', 3, 'na čekanju', '2024-02-12 17:38:23', 29, 0, 0, NULL, 'images/hapsenje_prostitucija.jpg');
INSERT INTO `vest` (`id_vesti`, `naslov`, `sadrzaj`, `id_rubrike`, `status`, `datum_vreme_objave`, `id_novinara`, `broj_pozitivnih`, `broj_negativnih`, `id_urednika`, `lead_slika_url`) VALUES
(165, 'VUKE MAKRO\" SVE PRIZNAO O BRAĆI PANIĆ I UČEŠĆU U LANCU PROSTITUCIJE! Pušten da se brani sa slobode, pa objavio ŠOK SLIKU', '<p>Posle pritvora od 48 časova,&nbsp;<strong><a href=\"https://www.kurir.rs/crna-hronika/4352311/ovo-je-drug-brace-panic-sa-njim-uhapsena-i-jedna-zena\" target=\"_blank\" rel=\"noopener\">osumnjičeni Vuk Stanković</a></strong>&nbsp;pu&scaron;ten je iz policije. On je, podsetimo, uhap&scaron;en zbog posredovanja u lancu prostitucije.</p>\r\n<p>Prilikom saslu&scaron;anja rekao je da se kaje zbog svojih radnji, te je ispričao svaki detalj, svoju ulogu u organizovanju prostitucije, ali i ulogu braće Panić i radnje koje su oni preduzimali.</p>\r\n<div>&nbsp;</div>\r\n<p>On je, naime, tužiocu bez oklevanja rekao da priznaje delo i da će objasniti sve &scaron;to je učinio, a sam njegov iskaz je od velikog značaja za dalji tog postupka.</p>\r\n<p>Kod Vuka Stankovića, izostali su zakonski osnovi za produženje pritvora, s obzirom na sve okolnosti, priznanje okrivljenog i obja&scaron;njenja radnji koje su preduzimali braća Panić. Nakon izlaska na slobodu se oglasio na Instagramu i objavio forografiju uz Muzeja iluzija, na kojoj pozira iza zatvorskih re&scaron;etaka.</p>\r\n<figure style=\"text-align: center;\"><img style=\"width: 462px; height: 349px; display: block; margin-left: auto; margin-right: auto;\" src=\"https://www.kurir.rs/data/images/2024/02/11/17/3813582_makro_ff.jpg?ver=1707671092\" alt=\"Vuk Stanković, makro\">\r\n<figcaption>FOTO: PRINTSCREEN/INSTAGRAM</figcaption>\r\n</figure>\r\n<p>Podsetimo, za&nbsp;<strong><a href=\"https://www.kurir.rs/tag/1045476/uros-panic\" target=\"_blank\" rel=\"noopener\">braćom Uro&scaron;em i Milo&scaron;em Panićem</a></strong>&nbsp;raspisana je potraga zbog sumnje da su posredovali u lancu prostitucije, a hap&scaron;enje su, kako saznajemo, izbegli samo par sati pre policijske akcije. Zbog posredovanja uhap&scaron;en je i njihov prijatelj Vuk Stanković, a na jednom od snimaka sa dru&scaron;tvenih mreža čuje se i kako ga braća nazivaju \"makroom\".</p>\r\n<p>Naime, Stanković je, kako se sumnja, vodio stranicu na \"Instagramu\" gde je reklamirao salone za masažu, a sumnja se da je upravo to bilo paravan za nelegalan posao, prostituciju.</p>\r\n<p>- On je na jednom sajtu eksplicitnog sadržaja objavljivao oglase za posao maserki i nudio da devojke mogu da zarade i do 100 evra dnevno - podseća izvor Kurira.</p>', 3, 'draft', '2024-02-12 17:39:36', 29, 0, 0, NULL, 'images/hronika.jpg');

